NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Anfang der frohen Botschaft von Jesus Christus, dem Sohne Gottes.',
        2: 'So, wie geschrieben steht bei dem Propheten Isaias: "Siehe, ich sende meinen Engel vor dir her, der dir den Weg bereiten soll."',
        3: 'Eine Stimme ruft in der Steppe: \'Richtet her den Weg des Herrn, macht seine Pfade eben."\'',
        4: 'Johannes trat in der Steppe auf, taufte und verkündete die Taufe der Bekehrung zur Nachlassung der Sünden.',
        5: 'Das ganze Land Judäa zog zu ihm hinaus, sowie alle Bewohner Jerusalems. Man ließ sich von ihm im Jordanfluß taufen, wobei man seine Sünden bekannte.',
        6: 'Johannes trug ein Kleid aus Kamelhaaren und einen Ledergürtel um die Lenden; er nährte sich von Heuschrecken und wildem Honig.',
        7: 'Er predigte und sprach: "Nach mir kommt einer, der mächtiger ist als ich; ich bin nicht wert, mich vor ihm hinzubeugen und ihm die Riemen seiner Schuhe loszulösen.',
        8: 'Ich habe euch nur mit Wasser getauft. Er aber wird euch mit dem Heiligen Geiste taufen."',
        9: 'In jenen Tagen kam Jesus von Nazareth in Galiläa und ließ sich im Jordan von Johannes taufen.',
        10: 'Und sogleich, als er aus dem Wasser stieg, sah er, wie sich die Himmel öffneten und wie der Geist einer Taube gleich auf ihn niederschwebte und über ihm blieb.',
        11: 'Und eine Stimme kam vom Himmel her: "Du bist mein geliebter Sohn; an dir habe ich mein Wohlgefallen."',
        12: 'Und gleich hernach trieb ihn der Geist in die Einsamkeit',
        13: 'Vierzig Tage und vierzig Nächte war er in der Einsamkeit und ward vom Satan versucht; er lebte bei den wilden Tieren; doch Engel dienten ihm.',
        14: 'Nach der Gefangennahme des Johannes begab sich Jesus nach Galiläa und verkündete die frohe Botschaft vom Reiche Gottes.',
        15: 'Er sprach: "Erfüllt ist die Zeit; das Reich Gottes ist nahe! Bekehret euch und glaubt an die frohe Botschaft!"',
        16: 'Einst wanderte er an Galiläas Meer entlang, als er den Simon und Andreas, Simons Bruder, sah. Sie warfen eben ein Netz ins Wasser aus; sie waren nämlich Fischer.',
        17: 'Und Jesus sprach zu ihnen: "Kommt, folget mir! Ich werde euch zu Menschenfischern machen."',
        18: 'Augenblicklich ließen sie ihre Netze liegen und folgten ihm.',
        19: 'Er ging ein wenig weiter; da sah er Jakobus, den Sohn des Zebedäus, und Johannes, seinen Bruder. In ihrem Boote legten sie gerade die Netze sich zurecht.',
        20: 'Sogleich berief er sie. Sie ließen ihren Vater Zebedäus im Boot bei den Tagelöhnern und gingen mit ihm fort.',
        21: 'Sie gingen nach Kapharnaum hinein. Gleich am Sabbat begab er sich in die Synagoge, wo er lehrte.',
        22: 'Man war von seiner Lehre hingerissen; denn er lehrte sie wie einer, der Vollmacht hat, und nicht wie die Schriftgelehrten.',
        23: 'In ihrer Synagoge war ein Mensch im Banne eines unreinen Geistes. Er schrie laut',
        24: 'und rief: "Oho! Was willst du von uns, Jesus von Nazareth? Bist du gekommen, uns zu verderben? Ich weiß, wer du bist: der Heilige Gottes."',
        25: 'Doch Jesus drohte ihm und sprach: "Schweig! Fahr von ihm aus!"',
        26: 'Da zerrte ihn der unreine Geist hin und her und fuhr mit gellendem Geschrei von ihm aus.',
        27: 'Alle entsetzten sich und stritten miteinander. Sie fragten: "Was ist doch das, die neue Lehre in der Vollmacht Gottes? Gebietet er doch selbst unreinen Geistern, und sie gehorchen ihm."',
        28: 'Sein Ruf ging überall hinaus ins ganze Gebiet von Galiläa.',
        29: 'Dann ging er aus der Synagoge fort und kam ins Haus des Simon und Andreas, in der Begleitung von Jakobus und Johannes.',
        30: 'Die Schwiegermutter des Simon lag fieberkrank darnieder, und sie erzählten ihm sofort von ihr.',
        31: 'Da trat er zu ihr hin, ergriff sie bei der Hand und richtete sie auf. Da wich von ihr das Fieber, und sie diente ihnen.',
        32: 'Als es Abend wurde und die Sonne untergegangen war, brachte man zu ihm alle Kranken und Besessenen.',
        33: 'Die ganze Stadt drängte sich vor der Tür zusammen.',
        34: 'Er heilte viele Kranke von mannigfachen Leiden und trieb auch viele Dämonen aus; doch ließ er es nicht zu, daß die Dämonen redeten; sie erkannten ihn nämlich.',
        35: 'Frühmorgens, als es noch ganz dunkel war, stand er auf, ging fort und kam an einen abgelegenen Ort, wo er betete.',
        36: 'Simon und die Seinen gingen ihm rasch nach.',
        37: 'Sie fanden ihn und sagten zu ihm: "Alle suchen dich."',
        38: 'Er sprach zu ihnen: "Laßt uns auch anderswohin gehen, in die Flecken da umher, damit ich auch dort predige; dazu bin ich gekommen."',
        39: 'So zog er denn umher und predigte überall in Galiläa in ihren Synagogen und trieb die Dämonen aus.',
        40: 'Da kam zu ihm ein Aussätziger; auf den Knien flehte er ihn an und sprach: "Wenn du willst, kannst du mich rein machen."',
        41: 'Voll Erbarmen streckte er seine Hand aus, berührte ihn und sprach: "Ich will, sei rein!"',
        42: 'Und sofort wich der Aussatz von ihm, und er war rein.',
        43: 'Mit strengen Worten schickte er ihn alsbald fort',
        44: 'und sprach zu ihm: "Hüte dich, irgend jemand etwas zu sagen; geh vielmehr hin, zeige dich dem Priester und opfere für deine Reinigung, was Moses vorgeschrieben hat; sie mögen dies zum Zeugnis nehmen."',
        45: 'Jener ging hinweg; er wußte vieles zu erzählen und machte die Tat überall bekannt. So kam es, daß Jesus sich nicht mehr offen in einer Stadt zeigen konnte, vielmehr sich außerhalb an abgelegenen Orten aufhielt; jedoch kam man zu ihm von allen Seiten.',
    },
    2: {
        1: 'Ein paar Tage später kam er wieder nach Kapharnaum. Man erfuhr, daß er im Hause sei.',
        2: 'So viele strömten zusammen, daß selbst vor der Tür kein Platz mehr war. Und er legte ihnen das Wort aus.',
        3: 'Da kamen einige daher und brachten zu ihm einen Lahmen; vier Männer trugen ihn.',
        4: 'Doch des Gedränges wegen konnten sie nicht zu ihm kommen; da deckten sie gerade, wo er stand, das Dach auf und schufen dadurch eine Öffnung und ließen die Bahre, auf welcher der Lahme lag, hinab.',
        5: 'Als Jesus ihren Glauben sah, sprach er zu dem Lahmen: "Mein Sohn, vergeben sind dir deine Sünden."',
        6: 'Es saßen aber einige der Schriftgelehrten dort, die in ihrem Herzen dachten:',
        7: '"Wie kann er nur so reden? Er lästert. Wer kann denn Sünden vergeben als nur der Eine, Gott?"',
        8: 'Doch Jesus erkannte sofort in seinem Geiste, daß sie solches bei sich dachten. Er sprach zu ihnen: "Was denkt ihr da in eurem Herzen?',
        9: "Was ist leichter, zu dem Lahmen zu sagen: 'Vergeben sind dir deine Sünden' oder zu sagen: 'Steh auf, nimm deine Bahre und geh umher?'",
        10: 'Ihr aber sollt wissen, daß der Menschensohn die Macht besitzt, auf Erden Sünden zu vergeben." Dann sprach er zum Gelähmten:',
        11: '"Ich sage dir: Steh auf, nimm deine Bahre und geh nach Hause!"',
        12: 'Und er stand auf, nahm seine Bahre und ging sogleich vor aller Augen weg. Alle waren außer sich, lobten Gott und sprachen: "So etwas haben wir noch nie gesehen."',
        13: 'Dann ging er wieder an das Meer hinaus. Die ganze Menge strömte zu ihm hin, und er lehrte sie.',
        14: 'Im Vorübergehen sah er Levi, des Alphäus Sohn, an der Zollstätte sitzen. Er sprach zu ihm: "Folge mir!" Da stand er auf und folgte ihm.',
        15: 'Als er in seinem Haus zu Tische saß, waren auch viele Zöllner und Sünder zu Tische mit Jesus und Seinen Jüngern. - Es gab schon viele, die sich ihm angeschlossen hatten. -',
        16: 'Die Schriftgelehrten bei den Pharisäern sahen, wie er mit Sündern und Zöllnern aß; sie fragten deshalb seine Jünger: "Warum ißt und trinkt er denn mit Zöllnern und Sündern?"',
        17: 'Jesus hörte dies und sprach: "Nicht die Gesunden brauchen einen Arzt, sondern die Kranken. Nicht dazu bin ich da, Gerechte zu berufen, sondern Sünder."',
        18: 'Die Jünger des Johannes und die Pharisäer hatten einmal einen Fasttag. Da kamen sie und fragten ihn: "Warum fasten die Jünger des Johannes und die Pharisäer; deine Jünger aber fasten nicht?"',
        19: 'Jesus sprach zu ihnen: "Können denn die Hochzeitsgäste fasten, solange der Bräutigam bei ihnen weilt? Solange sie den Bräutigam bei sich haben, können sie nicht fasten.',
        20: 'Es werden aber Tage kommen, da ihnen der Bräutigam entrissen ist; an jenen Tagen werden sie dann fasten.',
        21: 'Niemand näht einen Fleck aus ungewalktem Zeug auf einen alten Mantel; sonst reißt der neue Fleck auch noch vom alten Mantel etwas weg, und der Riß wird nur noch größer.',
        22: 'Auch füllt niemand neuen Wein in alte Schläuche; sonst sprengt der Wein die Schläuche, und Wein und Schläuche sind verdorben. Nein, neuen Wein muß man in neue Schläuche füllen."',
        23: 'An einem Sabbat ging er durch die Ährenfelder hin. Seine Jünger rupften im Vorübergehen Ähren ab.',
        24: 'Da sprachen die Pharisäer zu ihm: "Sieh, wie sie am Sabbat tun, was verboten ist."',
        25: 'Doch er sprach zu ihnen: "Habt ihr noch nie gelesen, was David tat, als er in Not war und er und seine Begleiter Hunger hatten?',
        26: 'Wie er das Haus Gottes betrat zur Zeit des Hohenpriesters Abjathar und dort die Schaubrote aß, die nur die Priester essen dürfen, und wie er auch noch seinen Gefährten gab?"',
        27: 'Und weiter sagte er zu ihnen: "Der Sabbat ist des Menschen wegen da und nicht der Mensch des Sabbats wegen.',
        28: 'Übrigens ist der Menschensohn auch Herr des Sabbats."',
    },
    3: {
        1: 'Dann ging er wieder in die Synagoge. Dort war ein Mann mit einer verwelkten Hand.',
        2: 'Da gaben sie nun acht, ob er ihn am Sabbat heile; denn sie wollten ihn verklagen.',
        3: 'Da sprach er zu dem Manne mit der verwelkten Hand: "Tritt hierher, in die Mitte!"',
        4: 'Dann fragte er sie: "Darf man am Sabbat Gutes oder Böses tun, ein Leben retten oder es zugrunde gehen lassen?" Jedoch sie schwiegen.',
        5: 'Voll Zorn sah er einen nach dem anderen an, in Trauer über die Verstocktheit ihres Herzens, und sprach dann zu dem Manne: "Strecke deine Hand aus!" Er streckte sie aus, und seine Hand war wiederhergestellt.',
        6: 'Die Pharisäer aber gingen weg und hielten gegen ihn mit den Herodianern Rat, wie sie ihn verderben könnten.',
        7: 'Darauf zog sich Jesus mit seinen Jüngern an das Meer zurück. Und große Scharen folgten ihm aus Galiläa und auch aus Judäa,',
        8: 'aus Jerusalem, Idumäa und aus der Gegend jenseits des Jordans; von Tyrus und von Sidon strömte man ihm in Scharen zu, weil man hörte, welch große Taten er vollbrachte.',
        9: 'Er sprach zu seinen Jüngern, sie sollten wegen dieser Menge ihm ein Boot bereithalten, damit er nicht ins Gedränge komme.',
        10: 'Denn er hatte viele geheilt, und so drängten alle Leidenden sich an ihn her, um ihn anzurühren.',
        11: 'Und wenn unreine Geister ihn erblickten, so fielen diese vor ihm nieder und schrien:',
        12: '"Du bist der Sohn Gottes." Er aber fuhr sie heftig an, daß sie ihn nicht offenbaren sollten.',
        13: 'Dann stieg er auf den Berg und rief die, die er wollte, zu sich, und sie gingen zu ihm hin.',
        14: 'Und er bestimmte zwölf, daß sie stets um ihn seien, die er dann aussenden könnte, um zu predigen,',
        15: 'und die auch Macht besäßen, Krankheiten zu heilen und die Dämonen auszutreiben.',
        16: 'Und er bestimmte die Zwölf. Er gab dem Simon den Namen Petrus;',
        17: 'Jakobus, den Sohn des Zebedäus, und Johannes, den Bruder des Jakobus, die hieß er Boanerges - d.h. Donnerer -;',
        18: 'sodann Andreas und Philippus, Bartholomäus, Matthäus, Thomas und Jakobus, des Alphäus Sohn, Thaddäus und Simon, den Eiferer,',
        19: 'sowie Judas, den Iskariot, der ihn dann verraten hat.',
        20: 'Er ging nach Hause. Da strömte wiederum viel Volk zusammen, so daß sie nicht einmal mehr essen konnten.',
        21: 'Als dies die Seinen hörten, kamen sie heraus, um ihn mit Gewalt hereinzuholen; denn sie sagten: "Er ist von Sinnen."',
        22: 'Und auch die Schriftgelehrten, die von Jerusalem hergekommen waren, sagten: "Dieser hat den Beelzebul" und "Durch den obersten der Dämonen treibt er die Dämonen aus."',
        23: 'Da rief er sie heran und sprach zu ihnen gleichnisweise: "Wie kann denn Satan den Satan austreiben?',
        24: 'Wenn ein Reich in sich uneins ist, kann dieses Reich nicht bestehen bleiben,',
        25: 'und wenn ein Haus in sich uneins ist, kann dieses Haus nicht bestehen bleiben.',
        26: 'Wenn Satan wider sich selbst auftreten würde und wenn er uneinig wäre, er könnte nicht bestehen; es wäre dann aus mit ihm.',
        27: 'Vielmehr kann keiner in das Haus des Starken eindringen und ihm seine Habe rauben, wenn er den Starken nicht zuvor gebunden hat. Dann erst kann er sein Haus ausplündern.',
        28: 'Wahrlich, ich sage euch: Alle Lästerungen und Sünden werden den Menschenkindern nachgelassen werden, mögen sie auch noch so schwere Lästerungen ausgestoßen haben;',
        29: 'nur wer gegen den Heiligen Geist Lästerungen ausspricht, wird in Ewigkeit nicht Nachlaß finden. Der ewigen Sünde wird er schuldig bleiben."',
        30: 'Sie sagten nämlich: "Dieser hat einen unreinen Geist."',
        31: 'Da kamen seine Mutter und seine Brüder; sie blieben draußen stehen und ließen ihn rufen.',
        32: 'Eine große Menge saß um ihn herum; da sagte man zu ihm: "Siehe, deine Mutter, deine Brüder und deine Schwestern suchen dich draußen."',
        33: 'Doch er sprach zu ihnen: "Wer ist meine Mutter, wer sind meine Brüder?"',
        34: 'Dann sah er alle, die im Kreis um ihn saßen, einen nach dem anderen an und sprach: "Seht, hier sind meine Mutter und meine Brüder.',
        35: 'Denn wer den Willen Gottes tut, der ist mir Bruder, Schwester, Mutter."',
    },
    4: {
        1: 'Dann fing er wieder an, am Meer zu lehren. Da sammelten bei ihm sich große Scharen, so daß er ein Boot besteigen mußte und sich draußen auf dem Meer niedersetzte; die ganze Menge aber stand am Meer entlang am Land.',
        2: 'Er lehrte sie viel in Gleichnissen. So sprach er in seinem Lehrvortrag zu ihnen:',
        3: '"Höret! Seht: Der Sämann ging aus zu säen.',
        4: 'Und als er säte, fiel ein Teil davon auf den Weg; die Vögel des Himmels kamen und fraßen es.',
        5: 'Anderes fiel auf steinigen Grund, wo es nicht viel Erdreich gab. Rasch schoß es in den Halm, es hatte nämlich keinen tiefen Boden;',
        6: 'doch als die Sonne aufgegangen war, wurde es versengt, und es verdorrte, weil es keine Wurzel hatte.',
        7: 'Ein anderes fiel unter Dornen; die Dornen wuchsen auf und erstickten es, und so gab es keine Frucht.',
        8: 'Ein anderes fiel auf guten Boden; es keimte, wuchs und brachte Frucht; es trug Frucht bis zu dreißig-, sechzig-, hundertfältig."',
        9: 'Er fügte dann noch bei: "Wer Ohren hat zu hören, höre!"',
        10: 'Als er allein war, fragten ihn die Leute, die bei ihm waren, sowie die Zwölf über die Gleichnisse.',
        11: 'Er sprach zu ihnen: "Euch ist das Geheimnis des Gottesreiches anvertraut; doch jenen, die draußen sind, wird das alles nur in Gleichnissen mitgeteilt,',
        12: 'damit sie mit offenen Augen sehen und doch nicht sehen, mit eigenen Ohren hören und doch nicht zur Einsicht kommen, damit sie sich nicht bekehren und Vergebung finden."',
        13: 'Und weiter sagte er zu ihnen: "Ihr versteht dieses Gleichnis nicht? Wie wollt ihr alle anderen verstehen?',
        14: 'Der Sämann sät das Wort.',
        15: "'Auf dem Wege' liegt es bei denen, wo das Wort gesät wird; doch kaum, daß sie es gehört, kommt der Satan und nimmt das Wort, das in ihnen gesät ward.",
        16: "Und ähnlich ist es 'auf steinigen Grund gesät' bei denen, die, wenn sie das Wort gehört haben, es sofort mit Freuden aufnehmen;",
        17: 'allein, sie haben in sich keine Wurzeln; denn sie sind unbeständig; kommt nämlich Trübsal oder Verfolgung um des Wortes willen, dann werden sie gleich irre.',
        18: "Andere sind die, wo es 'unter Dornen' gesät ward. Das sind die, die das Wort zwar hören;",
        19: 'jedoch die Sorgen dieser Welt, der Trug des Reichtums und ähnliche Gelüste drängen sich herein, ersticken das Wort, und so bleibt es ohne Frucht.',
        20: '\'Auf guten Boden\' ward gesät bei jenen, die das Wort gehört und in sich auf genommen haben und Frucht bringen: dreißig-, sechzig-, hundertfältig."',
        21: 'Des weiteren sprach er zu ihnen: "Läßt man sich wohl ein Licht bringen, um es unter einen Scheffel oder ein Bett zu stellen? Doch wohl, um es auf den Leuchter zu stellen.',
        22: 'Nichts ist verborgen, was nicht offenkundig werden, und nichts geheim, was nicht an den Tag kommen wird.',
        23: 'Wer Ohren hat zu hören, höre!"',
        24: 'Er sprach zu ihnen: "Gebt acht auf das, was ihr jetzt hört: Mit dem Maß, mit dem ihr messet, wird euch zugemessen werden; ja, wenn ihr hört, wird euch noch dreingegeben werden.',
        25: 'Wer nämlich hat, dem wird gegeben werden; aber wer nicht hat, dem wird auch das, was er besitzt, genommen werden."',
        26: 'Dann sprach er: "So ist es mit dem Gottesreich, wie wenn ein Mann den Samen übers Land wirft.',
        27: 'Er schläft und wacht wieder auf, so Nacht für Nacht und Tag für Tag. Und die Saat sproßt und wächst; wie, weiß er selber nicht.',
        28: 'Von selbst trägt die Erde Frucht; Saatgrün zuerst, dann Ähre und dann in der Ähre volles Korn.',
        29: 'Läßt es die Frucht zu, legt er sogleich die Sichel an: Die Erntezeit ist da."',
        30: 'Und weiter sprach er: "Womit sollen wir das Gottesreich vergleichen, oder in welches Gleichnis sollen wir es kleiden?',
        31: 'Es ist wie ein Senfkörnlein. Wenn man es in die Erde sät, ist es das kleinste unter allen Samenkörnern auf der Erde.',
        32: 'Ist es aber gesät, so geht es auf und wird das größte unter allen Gartenkräutern; es treibt so große Zweige, daß unter seinem Schatten die Vögel des Himmels nisten können."',
        33: 'In vielen solchen Gleichnissen verkündete er ihnen das Wort so, wie sie es eben fassen konnten.',
        34: 'Ohne Gleichnis redete er nicht zu ihnen; war er dann allein, erklärte er alles seinen Jüngern.',
        35: 'Am selben Tage, gegen Abend, sagte er zu ihnen: "Laßt uns hinüberfahren."',
        36: 'Und sie schickten die Menge fort und nahmen ihn, so wie er war, mit in ihr Boot. Auch andere Boote fuhren mit.',
        37: 'Doch da erhob sich ein gewaltiger Wirbelsturm; die Wogen schlugen in das Boot, und das Boot begann schon, sich zu füllen.',
        38: 'Er befand sich hinten im Boot und schlief auf einem Kissen. Sie weckten ihn und riefen: "Meister, kümmert es dich nicht, daß wir zugrunde gehen?"',
        39: 'Und er stand auf, gebot dem Wind und sprach zum Meere: "Schweig! Sei still!" Da legte sich der Wind, und es entstand lautlose Stille.',
        40: 'Darauf sprach er zu ihnen: "Was seid ihr denn so furchtsam? Wie? Habt ihr noch immer keinen Glauben?"',
        41: 'Und es befiel sie große Furcht; sie sprachen untereinander: "Wer ist wohl dieser, daß ihm Wind und Meer gehorchen?"',
    },
    5: {
        1: 'So kamen sie übers Meer hinüber in das Land der Gerasener.',
        2: 'Kaum war er aus dem Boot gestiegen, da lief ihm sogleich aus den Gräbern ein Mensch entgegen, der von einem unreinen Geist besessen war.',
        3: 'Er hauste in den Gräbern, und niemand konnte ihn fesseln, auch nicht mit einer Kette.',
        4: 'Man hatte ihn zwar oft an Händen und Füßen schon gefesselt, jedoch die Ketten hatte er gesprengt, die Fesseln durchgerieben, und niemand war imstande, ihn zu bändigen.',
        5: 'So war er denn beständig, Tag und Nacht, in Gräbern und auf Bergeshöhen, schrie und schlug sich selbst mit Steinen.',
        6: 'Da sah er Jesus aus der Ferne; er lief herzu, fiel vor ihm auf den Boden nieder',
        7: 'und schrie laut und gellend auf: "Was willst du von mir, Jesus, du Sohn des allerhöchsten Gottes? Ich beschwöre dich bei Gott: Quäle mich nicht!"',
        8: 'Denn schon sprach er zu ihm: "Unreiner Geist, fahr aus von diesem Menschen!"',
        9: 'Er fragte ihn: "Wie ist dein Name?" "Mein Name ist Legion", antwortete er ihm, "denn unser sind gar viele."',
        10: 'Er bat ihn flehentlich, sie doch nicht aus dem Lande zu vertreiben.',
        11: 'Nun war am Berge dort eine große Schweineherde auf der Weide.',
        12: 'Sie baten ihn und sprachen: "Schick uns zu den Schweinen, auf daß wir in sie fahren!"',
        13: 'Er gewährte es ihnen. Da fuhren die unreinen Geister aus und in die Schweine; die Herde raste am Abhang hin und ins Meer hinein, ungefähr zweitausend Stück, und sie ertranken im Meere.',
        14: 'Ihre Hirten flohen und erzählten es in der Stadt und auf dem Lande. Und sie kamen, um zu sehen, was vorgefallen war.',
        15: 'Sie gingen auch zu Jesus und sahen den Besessenen, der die Legion gehabt, bekleidet und vernünftig dasitzen. Da gerieten sie in Furcht.',
        16: 'Die zugesehen hatten, erzählten ihnen, was mit dem Besessenen und den Schweinen vorgefallen war.',
        17: 'Da baten sie ihn dringend, er möge sich aus ihren Grenzen entfernen.',
        18: 'Als er das Boot besteigen wollte, da bat ihn der Besessene, ob er nicht mit ihm gehen dürfe.',
        19: 'Doch er gestattete es nicht; er sprach zu ihm: "Geh heim zu den Deinen; erzähle ihnen, was der Herr an dir Großes getan und wie er sich deiner erbarmt hat."',
        20: 'Da ging er hin und verkündete in der Dekapolis, was Jesus ihm getan hatte; und alle mußten staunen.',
        21: 'Und Jesus fuhr im Boot wieder zum anderen Ufer hin, und es versammelte sich bei ihm viel Volk. Er hielt sich immer noch am Meere auf.',
        22: 'Da kam einer der Synagogenvorsteher; er hieß Jairus. Er sah ihn und fiel ihm zu Füßen',
        23: 'und bat ihn flehentlich: "Mein Töchterchen liegt im Sterben; daß du doch kommen und ihm die Hände auflegen wolltest, damit es gerettet sei und lebe."',
        24: 'Er ging mit ihm. Viel Volk ging hintendrein, und sie umdrängten ihn.',
        25: 'Da war ein Weib, das schon zwölf Jahre am Blutfluß litt',
        26: 'und von vielen Ärzten schon vieles hatte leiden müssen und seine ganze Habe ohne jeden Nutzen aufgewendet hatte; im Gegenteil, nur immer schlimmer war es gegangen.',
        27: 'Sie hatte von Jesus gehört und kam jetzt in der Menge hinterher und berührte sein Gewand.',
        28: 'Denn also dachte sie: "Wenn ich auch nur seine Kleider berühre, so ist mir schon geholfen."',
        29: 'Und ihr Blutfluß hörte sogleich auf; sie spürte es an ihrem Leibe, daß sie von ihren Leiden geheilt sei.',
        30: 'Doch Jesus merkte alsbald an sich, daß eine Kraft von ihm ausgegangen sei. Deshalb wandte er sich zu der Menge um und fragte: "Wer hat meine Kleider angerührt?"',
        31: 'Da sprachen seine Jünger zu ihm: "Du siehst doch, wie die Menge dich umdrängt; da fragst du noch: \'Wer hat mich angerührt?\'"',
        32: 'Jedoch, er schaute nach der um, die es getan hatte.',
        33: 'Das Weib, das wußte, was mit ihr geschehen war, kam mit Zittern und Zagen heran, fiel vor ihm nieder und sagte ihm die volle Wahrheit.',
        34: 'Er aber sprach zu ihr: "Meine Tochter! Dein Glaube hat dir geholfen. Geh hin im Frieden und sei von deinem Leiden geheilt!"',
        35: 'Noch sprach er so, da kamen Boten vom Hause des Synagogenvorstehers und sagten: "Deine Tochter ist gestorben. Wozu bemühst du noch den Meister?"',
        36: 'Jesus, der mitangehört hatte, was da geredet wurde, sprach zum Synagogenvorsteher: "Hab keine Furcht! Glaube nur!"',
        37: 'Und niemand durfte ihn begleiten als Petrus, Jakobus und Johannes, der Bruder des Jakobus.',
        38: 'Sie kamen in das Haus des Synagogenvorstehers; hier hörte er den Lärm, das Weinen und das laute Klagen.',
        39: 'Er ging hinein und sprach zu ihnen: "Was lärmt und weint ihr? Das Mädchen ist nicht tot; es schläft nur."',
        40: 'Da verlachten sie ihn. Er aber schickte alle weg, nahm nur den Vater und die Mutter des Kindes mit sich und die bei ihm waren und ging hinein, wo das Mädchen lag.',
        41: 'Dann faßte er das Mädchen bei der Hand und sprach zu ihm: "Talitha kumi!" - d.h. "Mädchen, steh auf!" -',
        42: 'Und sogleich stand das Mädchen auf und ging umher; es war zwölf Jahre alt. Sie gerieten vor Staunen ganz außer sich.',
        43: 'Er schärfte ihnen streng ein, daß niemand es erfahren dürfe; dann ließ er ihm zu essen geben.',
    },
    6: {
        1: 'Er ging von dort hinweg und kam in seine Vaterstadt, und seine Jünger begleiteten ihn.',
        2: 'Als es wieder Sabbat war, lehrte er in der Synagoge, und viele, die ihn hörten, fragten voll Erstaunen: "Woher mag er all dies haben? Welche Weisheit ward ihm verliehen! Welch große Wunder geschehen durch seine Hände!',
        3: 'Ist das nicht der Zimmermann, der Sohn der Maria und der Bruder des Jakobus, Joses, Judas und des Simon? Und wohnen denn nicht seine Schwestern hier bei uns?" So nahm man an ihm Anstoß.',
        4: 'Doch Jesus sprach zu ihnen: "Ein Prophet gilt nirgends weniger als in seiner Vaterstadt, bei seinen eigenen Verwandten und in seinem Vaterhause."',
        5: 'Er konnte dort kein einziges Wunder wirken; nur daß er einigen Kranken die Hand auflegte und sie heilte.',
        6: 'Und er wunderte sich wegen ihres Unglaubens. Und lehrend zog er durch die Dörfer ringsumher.',
        7: 'Alsdann rief er die Zwölf zu sich und begann, sie auszusenden, zu je zweien; auch gab er ihnen Macht über unreine Geister.',
        8: 'Weiter gebot er ihnen, nichts mitzunehmen auf den Weg als einen Stab, kein Brot und keinen Bettelsack und keine Münze im Gürtel.',
        9: 'Doch dürften sie Sandalen tragen, aber nicht zwei Röcke.',
        10: 'Ferner sprach er zu ihnen: "Betretet ihr irgendwo ein Haus, dann bleibt dort, bis ihr weiterzieht.',
        11: 'Doch wo man euch nicht aufnimmt und auf euch nicht hört, da geht weg von dort und schüttelt den Staub von euren Füßen ihnen zum Zeugnis."',
        12: 'So zogen sie nun hin und predigten, man solle Buße tun.',
        13: 'Sie trieben viele Geister aus, salbten viele Kranke mit Öl und heilten sie.',
        14: 'Die Kunde drang auch zum König Herodes; war doch sein Name in aller Mund. Er sprach: "Johannes der Täufer ist von den Toten auferstanden. Darum wirken in ihm Gottes Kräfte."',
        15: 'Doch andere behaupteten, er sei Elias; und wieder andere, er sei ein Prophet, wie einer aus den früheren Propheten.',
        16: 'Herodes aber meinte, als er davon hörte: "Johannes, den ich habe enthaupten lassen, ist wieder von den Toten auferstanden."',
        17: 'Eben der Herodes hatte nämlich den Johannes gefangennehmen lassen und im Gefängnis ihn verwahrt wegen der Herodias, dem Weibe des Philippus, seines Bruders, die er geheiratet hatte.',
        18: 'Denn Johannes hatte dem Herodes vorgehalten: "Es ist dir nicht erlaubt, das Weib deines Bruders zu haben."',
        19: 'Darum war die Herodias auf ihn erbost und hätte ihn gern töten lassen; sie brachte es aber nicht zuwege.',
        20: 'Herodes hatte nämlich vor Johannes Ehrfurcht; er wußte, daß er ein gerechter und heiliger Mann war. So nahm er ihn in Schutz. Wenn er ihn anhörte, geriet er oft in Zwiespalt mit sich selbst, und trotzdem hörte er ihn gern.',
        21: 'Da kam ein sehr gelegener Tag. An seinem Geburtsfest gab Herodes seinen Würdenträgern, den Obersten und Vornehmsten in Galiläa ein Mahl.',
        22: 'Da trat die Tochter eben der Herodias herein und tanzte. Und dies gefiel Herodes und den Gästen so, daß der König zu dem Mädchen sprach: "Erbitte von mir, was du willst; ich werde es dir geben."',
        23: 'Ja, er schwur ihr: "Was du von mir verlangst, will ich dir geben, und sollte es auch die Hälfte meines Reiches sein."',
        24: 'Sie ging hinaus und fragte ihre Mutter: "Was soll ich verlangen?" Und diese sagte: "Den Kopf Johannes des Täufers."',
        25: 'Alsdann trat sie voll Eifer vor den König hin und bat: "Ich will, laß mir sogleich auf einer Schüssel den Kopf Johannes des Täufers geben.',
        26: 'Da ward der König tief bestürzt; jedoch seiner Schwüre und der Gäste wegen wollte er sie nicht abweisen.',
        27: 'Der König schickte sogleich einen Henker weg mit dem Befehl, seinen Kopf zu bringen. Der ging hinweg und enthauptete ihn im Gefängnis',
        28: 'und brachte seinen Kopf auf einer Schüssel, gab ihn dem Mädchen, und das Mädchen gab ihn seiner Mutter.',
        29: 'Als seine Jünger davon hörten, kamen sie und holten seinen Leichnam und bargen ihn in einem Grabe.',
        30: 'Nun kehrten die Apostel wiederum zu Jesus zurück und erzählten ihm alles, was sie gewirkt und gepredigt hatten.',
        31: 'Er sprach zu ihnen: "Kommt mit, ihr ganz allein, an einen abgelegenen Ort und ruht euch ein wenig aus." Denn viele gingen ab und zu, so daß sie nicht einmal Zeit zum Essen hatten.',
        32: 'Sie fuhren also für sich allein in einem Boot an einen abgelegenen Ort.',
        33: 'Doch viele sahen, wie sie von dannen gingen, und erkannten ihre Absicht. Aus allen Städten strömten sie dorthin zu Fuß zusammen und kamen noch vor ihnen an.',
        34: 'Er stieg aus und sah die große Menge, und er empfand ein herzliches Erbarmen über sie; sie waren wie Schafe ohne Hirten. Und er begann, sie mancherlei zu lehren.',
        35: 'Als es schon spät geworden war, traten seine Jünger zu ihm hin und sprachen: "Einsam ist der Ort und auch die Zeit schon vorgerückt.',
        36: 'Entlaß sie! Sie mögen in die Dörfer und die Flecken hier im Umkreis gehen und Nahrung für sich kaufen."',
        37: 'Er aber sprach zu ihnen: "Gebt ihr ihnen zu essen!" Da sagten sie zu ihm: "Sollen wir denn gehen und Brot für zweihundert Zehner kaufen und ihnen dann zu essen geben?"',
        38: 'Er fragte sie: "Wieviel Brote habt ihr? Geht und seht nach!" Sie sahen nach und sagten: "Fünf, und zwei Fische."',
        39: 'Dann ließ er alle in Gruppen auf dem grünen Rasen sich lagern.',
        40: "Sie ließen sich nun Reih' an Reihe nieder, zu je hundert und je fünfzig.",
        41: 'Dann nahm er die fünf Brote und die zwei Fische; er sah zum Himmel auf, segnete und brach die Brote und gab sie den Jüngern, um sie ihnen vorzulegen. Auch die zwei Fische ließ er unter alle verteilen.',
        42: 'Und alle aßen und wurden satt;',
        43: 'ja, noch zwölf Körbe trugen sie hinweg, voll mit Stücken, auch von den Fischen.',
        44: 'Derer, die gegessen hatten, waren es fünftausend Männer.',
        45: 'Sogleich drängte er die Jünger, in das Boot zu steigen und an das andere Ufer nach Bethsaida weiterzufahren, ihm voraus, während er selbst die Scharen entlassen wollte.',
        46: 'Und er entließ sie und stieg auf einen Berg, um zu beten.',
        47: 'Es war schon spät; das Boot war mitten auf dem Meer und er allein noch an Land.',
        48: 'Er sah, wie sie im Dahinfahren hart bedrängt waren; sie hatten nämlich Gegenwind. Da, um die vierte Nachtwache, kam er zu ihnen auf dem Meer daher. Er wollte an ihnen vorübergehen.',
        49: 'Sie sahen ihn, wie er auf dem Meer wandelte, und meinten, es sei ein Gespenst, und schrien laut auf.',
        50: 'Denn alle sahen ihn und erschraken. Doch alsbald redete er sie an und sprach zu ihnen: "Nur Mut! Ich bin es. Habt keine Angst!"',
        51: 'Dann stieg er zu ihnen ins Boot, und sogleich legte sich der Wind. Jetzt gerieten sie erst recht ganz außer sich;',
        52: 'das mit den Broten nämlich hatten sie noch nicht verstanden; ihr Sinn war immer noch verschlossen.',
        53: 'Sie fuhren vollends hinüber und kamen bei Genesareth ans Land.',
        54: 'Und wie sie aus dem Boote stiegen, ward er sofort erkannt.',
        55: 'Man lief die ganze Gegend aus und trug voll Eifer Kranke auf Betten dahin, wo sie hörten, daß er sei.',
        56: 'Wo immer er Dörfer, Städte oder Gehöfte betrat, da legte man die Kranken auf die Plätze und bat ihn, sie möchten nur den Saum seines Kleides berühren dürfen. Und alle, die ihn berührten, wurden gesund.',
    },
    7: {
        1: 'Da kamen zu ihm Pharisäer und einige Schriftgelehrte aus Jerusalem.',
        2: 'Und da sie sahen, daß etliche seiner Jünger mit "gemeinen", das heißt mit ungewaschenen, Händen ihre Mahlzeit hielten',
        3: '(-die Pharisäer und die Juden überhaupt essen nämlich nicht, ehe sie sich die Hände nicht mit einer Handvoll Wasser gewaschen haben, getreu der Überlieferung der Alten.',
        4: 'Auch wenn sie von dem Markt kommen, so essen sie nicht, ohne sich gewaschen zu haben. Auch sonst gibt es noch vieles andere, was sie streng nach der Überlieferung beobachten: Abspülung von Bechern, Krügen, Kesseln Bettgestellen.-),',
        5: 'fragten die Pharisäer und die Schriftgelehrten ihn also: "Warum leben deine Jünger nicht nach der Überlieferung der Alten, sondern essen mit \'gemeinen\' Händen?"',
        6: 'Da sagte er zu ihnen: "Richtig hat Isaias über euch, ihr Heuchler, schon geweissagt; denn also steht geschrieben: \'Dieses Volk ehrt mich mit den Lippen; ihr Herz jedoch ist weit von mir;',
        7: "nichtig ist ihr Gottesdienst; Menschensatzungen machen sie zu ihrer Lehre.'",
        8: 'Ihr gebt das Gebot Gottes preis und haltet euch an die Überlieferung der Menschen; Abspülung von Krügen, Bechern und vieles andere dergleichen tut ihr."',
        9: 'Er fuhr dann fort: "Gar trefflich schiebt ihr das Gebot Gottes beiseite, um eure Überlieferung zu wahren.',
        10: "Moses hat einst geboten: 'Du sollst Vater und Mutter ehren!' und 'Wer Vater oder Mutter schmäht, soll sterben!'",
        11: "Ihr aber sagt: 'Wer zu Vater oder Mutter spricht: Was ich dir zu leisten hätte, ist 'korban' - d.h. Opfergabe -,",
        12: 'dann laßt ihr ihn für Vater oder Mutter nichts mehr tun.',
        13: 'Also entkräftet ihr, was Gott gesprochen hat, durch eure Überlieferung, die ihr überliefert habt. Und dergleichen treibt ihr noch viel."',
        14: 'Er rief sodann die Scharen wieder zu sich her und sprach zu ihnen: "Hört alle und versteht es wohl.',
        15: 'Nichts gibt es, was von außen in den Menschen kommt und ihn unrein machen könnte; nein, was vom Menschen ausgeht, das macht den Menschen unrein.',
        16: 'Wer Ohren hat zu hören, der höre!"',
        17: 'Als er von der Menge weg ins Haus getreten war, da fragten ihn die Jünger nach dem Gleichnis.',
        18: 'Er sprach zu ihnen: "Seid denn auch ihr immer noch unverständig? Versteht ihr wirklich nicht, daß, was immer von außen in den Menschen kommt, ihn nicht unrein machen kann,',
        19: 'weil es nicht in sein Herz eingeht, sondern in den Magen und den naturgemäßen Ausgang nimmt." - Alle Speisen erklärte er damit für rein. -',
        20: '"Was aber aus dem Menschen kommt", so fuhr er fort, "das macht den Menschen unrein. 21 Von innen, aus den Herzen der Menschen, gehen schändliche Gedanken, Unzucht, Diebstahl, Mord,',
        22: 'Ehebruch, Habgier, Bosheit, Arglist, Ausschweifung, Neid, Lästerung, Hochmut, Unverstand hervor.',
        23: 'Alle diese bösen Dinge kommen aus dem Innern, und sie machen den Menschen unrein."',
        24: 'Dann brach er auf und ging von dort hinweg ins Land von Tyrus und Sidon. Er begab sich in ein Haus, doch wollte er es niemand wissen lassen; allein er konnte nicht verborgen bleiben.',
        25: 'Ein Weib, dessen Töchterchen von einem unreinen Geist besessen war, hatte schon von ihm erfahren. Sie kam herzu und fiel ihm zu Füßen.',
        26: 'Das Weib war eine Heidin und stammte aus dem syrischen Phönizien. Sie bat ihn, daß er den Dämon aus ihrer Tochter austreibe.',
        27: 'Er aber sprach zu ihr: "Laß doch die Kinder erst einmal gesättigt werden! Es ist nicht recht, den Kindern das Brot wegzunehmen und es den Hunden vorzuwerfen."',
        28: 'Doch sie entgegnete und sprach zu ihm: "Gewiß, o Herr! Doch auch die Hunde unterm Tisch fressen, was die Kinder übriglassen."',
        29: 'Da sagte er zu ihr: "Um dieses Wortes willen geh heim! Der Dämon ist aus deiner Tochter ausgefahren."',
        30: 'Sie ging nach Hause, fand das Kind auf seinem Bett liegen; der Dämon war wirklich ausgefahren.',
        31: 'Und er verließ das Land von Tyrus wieder und begab sich über Sidon mitten in das Gebiet der Dekapolis hinein an das Meer von Galiläa.',
        32: 'Da brachte man ihm einen Tauben, der zugleich stumm war, und bat ihn, daß er ihm die Hand auflege.',
        33: 'Er nahm ihn aus der Menge weg, abseits, und legte ihm seine Finger in die Ohren, berührte seine Zunge mit Speichel,',
        34: 'schaute zum Himmel auf, seufzte und sprach zu ihm: "Effetha!" das heißt: Tu dich auf!',
        35: 'Und sogleich waren ihm die Ohren aufgetan; gelöst war das Band seiner Zunge, und er konnte richtig sprechen.',
        36: 'Jedoch er verbot ihnen, dies weiter auszusagen; allein je strenger er es ihnen verwehrte, desto weiter machten sie es bekannt.',
        37: 'Und man staunte über alle Maßen und sagte: "Er macht alles wohl; die Tauben macht er hören und die Stummen reden."',
    },
    8: {
        1: 'In jenen Tagen war wieder einmal eine große Volksmenge beisammen und hatte nichts zu essen. Da rief er seine Jünger zu sich her und sprach zu ihnen:',
        2: '"Mich erbarmt des Volkes. Schon drei Tage harren sie bei mir aus und haben nichts zu essen.',
        3: 'Wenn ich sie hungrig nach Hause gehen lasse, könnten sie auf dem Weg verschmachten, und manche unter ihnen sind weit hergekommen."',
        4: 'Seine Jünger aber gaben ihm zur Antwort: "Wie sollte man sie hier in der Steppe mit Broten sättigen können?"',
        5: 'Da fragte er sie: "Wieviel Brote habt ihr denn?" Sie sprachen: "Sieben."',
        6: 'Nun hieß er die Leute, sich auf den Boden lagern. Dann nahm er die sieben Brote, dankte, brach sie und gab sie seinen Jüngern, daß diese sie austeilen möchten. Sie teilten sie der Menge aus.',
        7: 'Auch ein paar Fischlein hatten sie. Er segnete auch diese und ließ auch sie verteilen.',
        8: 'Sie aßen und wurden satt; sie trugen auch noch sieben Körbe weg mit Stücken, die übriggeblieben waren.',
        9: 'Es waren wohl an viertausend gewesen die gegessen hatten; alsdann entließ er sie.',
        10: 'Sogleich stieg er mit seinen Jüngern in das Boot, und er gelangte in die Gegend von Dalmanutha.',
        11: 'Da kamen auch die Pharisäer, und sie versuchten, sich mit ihm einzulassen. Sie wollten ihn auf die Probe stellen und verlangten von ihm ein Zeichen aus dem Himmel.',
        12: 'Da seufzte er aus tiefstem Herzensgrund und sprach: "Wozu verlangt dieses Geschlecht ein Zeichen? Wahrlich, ich sage euch: Diesem Geschlecht wird kein Zeichen gegeben werden."',
        13: 'Damit ließ er sie stehen, stieg wieder ein und fuhr ans andere Ufer.',
        14: 'Sie hatten vergessen, Brote mitzunehmen; nur ein einziges Brot hatten sie bei sich im Boote.',
        15: 'Er warnte sie und sprach zu ihnen: "Habt acht und hütet euch vor dem Sauerteig der Pharisäer und vor dem Sauerteig des Herodes!"',
        16: 'Sie besprachen sich und sagten schließlich: "Wir haben ja kein Brot bei uns."',
        17: 'Doch Jesus merkte dies und sprach zu ihnen: "Was besprecht ihr miteinander, weil ihr keine Brote habt; begreift und versteht ihr denn immer noch nicht? Ist euer Herz noch ganz verschlossen?',
        18: 'Ihr habt Augen, seht aber nicht, und Ohren habt ihr, hört aber nicht. Erinnert ihr euch denn nicht mehr,',
        19: 'daß ich fünf Brote für die Fünftausend brach? Wie viele Körbe, voll mit Stücken, habt ihr noch fortgetragen?" Sie sagten zu ihm: "Zwölf."',
        20: '"Und bei den sieben für die Viertausend: Wie viele Körbe, voll mit Stücken, habt ihr da noch fortgetragen?" Sie gaben ihm zur Antwort: "Sieben."',
        21: 'Er sprach zu ihnen: "Versteht ihr es denn immer noch nicht?"',
        22: 'Sie kamen nach Bethsaida. Dort brachte man ihm einen Blinden; sie baten ihn, er möge ihn nur berühren.',
        23: 'Er nahm den Blinden bei der Hand und führte ihn vors Dorf hinaus. Alsdann tat er Speichel in seine Augen, legte ihm die Hände auf und fragte ihn: "Siehst du etwas?"',
        24: 'Er sah auf und sagte: "Ich sehe die Menschen; ich sehe etwas wie Bäume, daß sie sich bewegen."',
        25: 'Dann legte er ihm die Hände nochmals auf die Augen. Sein Blick drang jetzt ganz durch, er wurde wiederhergestellt und konnte alles deutlich sehen.',
        26: 'Dann sandte er ihn heim und sprach: "Geh nicht ins Dorf hinein!"',
        27: 'Darauf ging Jesus mit seinen Jüngern in die Ortschaften von Cäsarea Philippi. Auf dem Wege fragte er seine Jünger: "Für wen halten mich die Leute?"',
        28: 'Sie gaben ihm zur Antwort: "Für Johannes den Täufer, andere für Elias, wieder andere für irgendeinen Propheten."',
        29: 'Da fragte er sie weiter: "Für wen haltet ihr mich?" Darauf gab ihm Petrus zur Antwort: "Du bist der Christus."',
        30: 'Er aber schärfte ihnen streng ein, sie sollten über ihn zu niemand reden.',
        31: 'Nun fing er an, sie zu belehren, daß der Menschensohn vieles leiden müsse; er müsse von den Ältesten, den Oberpriestern und den Schriftgelehrten verworfen werden, er müsse getötet werden, doch nach drei Tagen werde er wieder auferstehen.',
        32: 'Er sagte das ganz offen. Da nahm ihn Petrus beiseite und wollte ihm ernstlich zureden.',
        33: 'Er aber wandte sich um, und angesichts der Jünger schalt er Petrus mit den Worten: "Hinweg von mir, du Satan! Du hast nicht Sinn fürs Göttliche, sondern nur fürs Menschliche."',
        34: 'Alsdann rief er die Menge samt seinen Jüngern her und sprach zu ihnen: "Wer mir nachfolgen will, der verleugne sich selbst, nehme sein Kreuz auf sich und folge mir.',
        35: 'Denn wer sein Leben sich erhalten will, der wird es verlieren, und wer sein Leben mir und dem Evangelium zulieb verliert, der wird es erhalten.',
        36: 'Was nützte es dem Menschen, wenn er die ganze Welt gewänne, doch sein Leben dabei verlöre!',
        37: 'Was könnte auch einer geben als Kaufpreis für sein Leben?',
        38: 'Denn wer sich bei diesem Geschlecht voll Ehebruch und Sünde meiner und meiner Worte schämt, dessen wird auch der Menschensohn sich schämen, wenn er mitsamt den heiligen Engeln in der Herrlichkeit seines Vaters kommt."',
    },
    9: {
        1: 'Und weiter sprach er zu ihnen: "Wahrlich, ich sage euch: Es stehen solche hier, die den Tod nicht kosten werden, bis sie das Gottesreich in Macht erscheinen sehen."',
        2: 'Sechs Tage später nahm Jesus den Petrus, Jakobus und Johannes mit sich und führte sie allein auf einen hohen Berg abseits. Und er ward verwandelt vor ihnen.',
        3: 'Seine Kleider wurden schimmernd weiß, wie sie kein Walker auf der Erde bleichen kann.',
        4: 'Und es erschienen ihnen Elias mit Moses, die sich mit Jesus unterhielten.',
        5: 'Petrus nahm das Wort und sprach zu Jesus: "Rabbi, wie schön ist es doch, daß wir hier sind. Laß uns drei Hütten bauen: dir eine, dem Moses eine und dem Elias eine."',
        6: 'Er wußte nicht, was er sprach: sie waren vor Schrecken außer sich.',
        7: 'Doch da kam eine Wolke, die ihren Schatten auf sie warf, und eine Stimme aus der Wolke sprach: "Das ist mein vielgeliebter Sohn; auf diesen sollt ihr hören."',
        8: 'Rasch schauten sie umher, sie sahen aber niemand mehr bei sich als Jesus allein.',
        9: 'Während sie vom Berge niederstiegen, befahl er ihnen streng, niemand zu erzählen von dem, was sie gesehen hatten, bis der Menschensohn von den Toten auferstanden sei.',
        10: 'An diesem Worte blieben sie nun hängen und stritten miteinander, was das zu bedeuten habe: das Auferstehen von den Toten.',
        11: 'Sie fragten ihn und sprachen: "Es sagen aber doch die Pharisäer und Schriftgelehrten, Elias müsse vorher noch kommen?"',
        12: 'Er sprach zu ihnen: "Elias kommt allerdings vorher, und er wird alles wieder herstellen. Wie kann dann aber vom Menschensohn geschrieben sein, daß er viel leiden müsse und verkannt werde?',
        13: 'Gewiß, ich sage euch: Elias ist schon da. Doch hat man mit ihm angefangen, was man wollte, wie über ihn geschrieben steht."',
        14: 'Sie kamen zu den Jüngern und sahen eine große Menge um sie her, auch Schriftgelehrte, die mit ihnen stritten.',
        15: 'Sobald ihn die Menge erblickte, geriet sie in Erregung und eilte ihm entgegen, ihn zu grüßen.',
        16: 'Er fragte sie: "Worüber streitet ihr mit ihnen?"',
        17: 'Da erwiderte ihm einer aus der Menge: "Meister, ich brachte meinen Sohn zu dir, er ist von einem stummen Geiste besessen.',
        18: 'Wenn der ihn packt, zerrt er ihn hin und her; dann schäumt er und knirscht mit den Zähnen und liegt starr da. Ich bat deine Jünger, sie möchten ihn austreiben; sie hatten aber nicht die Kraft dazu."',
        19: 'Darauf erwiderte er ihnen: "O du ungläubiges Geschlecht. Wie lang noch muß ich bei euch bleiben? Wie lang noch muß ich euch ertragen? Bringt ihn her zu mir!"',
        20: 'Da brachten sie ihn zu ihm. Doch wie der Geist ihn erblickte, riß er den Knaben hin und her; dieser fiel zu Boden und wälzte sich schäumend.',
        21: 'Und Jesus fragte seinen Vater: "Wie lang schon hat er das?" Er sprach: "Von Kindheit an.',
        22: 'Oft wirft er ihn sogar ins Feuer oder auch ins Wasser, um ihn umzubringen. Wenn du das kannst, so hilf uns; hab Erbarmen mit uns."',
        23: 'Und Jesus sprach zu ihm: "Wenn du das kannst? Wer glaubt, kann alles."',
        24: 'Sofort rief der Vater des Knaben unter Tränen: "Ich glaube Herr. Hilf meinem Unglauben!"',
        25: 'Als Jesus sah, wie das Volk immer dichter zusammenströmte, bedrohte er den unreinen Geist und rief ihm zu: "Du stummer und tauber Geist, ich befehle dir, fahre aus von ihm und kehre niemals mehr in ihn zurück!"',
        26: 'Da schrie er auf, zerrte ihn heftig hin und her und fuhr dann von ihm aus. Der Knabe lag da wie tot, so daß die meisten sagten: "Er ist tot."',
        27: 'Doch Jesus nahm ihn bei der Hand und half ihm auf, und er stand aufrecht da.',
        28: 'Er ging darauf ins Haus. Insgeheim fragten ihn seine Jünger: "Warum konnten wir ihn nicht austreiben?"',
        29: 'Er aber sprach zu ihnen: "Diese Art kann man nur durch Beten und Fasten austreiben."',
        30: 'Sie gingen weg von dort und wanderten durch Galiläa hin; doch wollte er nicht, daß es jemand erfahre.',
        31: 'Denn er belehrte seine Jünger und sagte ihnen: "Der Menschensohn wird in die Hände der Menschen überliefert werden; man wird ihn töten; jedoch drei Tage nach seinem Tode wird er auferstehen."',
        32: 'Doch sie begriffen diese Rede nicht; sie scheuten sich indes, ihn zu fragen.',
        33: 'Sie kamen nach Kapharnaum. Zu Hause fragte er sie: "Worüber habt ihr unterwegs gestritten?"',
        34: 'Sie aber schwiegen. Sie hatten nämlich unterwegs miteinander gestritten, wer der Größte sei.',
        35: 'Er setzte sich und rief die Zwölf zu sich her und sprach zu ihnen: "Wer der Erste sein möchte, der sei der Letzte und der Diener aller."',
        36: 'Darauf nahm er ein Kind, stellte es mitten unter sie, schloß es in die Arme und sprach zu ihnen:',
        37: '"Wer ein solches Kind wie dieses hier in meinem Namen aufnimmt, nimmt mich auf; und wer mich aufnimmt, nimmt nicht mich auf, sondern den, der mich gesandt hat."',
        38: 'Johannes sprach zu ihm: "Meister, wir sahen einen, der in deinem Namen Dämonen austrieb, aber nicht mit uns geht. Wir suchten ihn zu hindern, weil er nicht mit uns geht."',
        39: 'Doch Jesus sprach: "Hindert ihn nicht! Keiner kann in meinem Namen Wunder wirken und gleich nachher wieder Böses von mir reden.',
        40: 'Wer nicht gegen uns ist, der ist für uns.',
        41: 'Wer euch in meinem Namen nur einen Becher Wassers zu trinken reicht, weil ihr Christus angehört, ich sage euch: Er wird seinen Lohn nicht verlieren.',
        42: 'Wer aber einem dieser Kleinen, die an mich glauben, Anlaß zur Sünde gibt, dem ist es besser, daß ihm ein Mühlstein an den Hals gehängt und er ins Meer geworfen wird.',
        43: 'Gibt dir deine Hand zur Sünde Anlaß, so hau sie ab! Besser ist es für dich, verstümmelt zum Leben einzugehen, als daß du zwei Hände habest und in die Hölle gehen mußt, ins unauslöschliche Feuer,',
        44: 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.',
        45: 'Gibt dir dein Fuß zur Sünde Anlaß, so hau ihn ab! Besser ist es für dich, hinkend zum Leben einzugehen, als daß du zwei Füße habest und in die Hölle geworfen wirst, ins unauslöschliche Feuer,',
        46: 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.',
        47: 'Gibt dir dein Auge zur Sünde Anlaß, so reiß es aus! Besser ist es für dich, mit einem Auge in das Reich Gottes einzugehen, als daß du zwei Augen habest und in die Hölle geworfen wirst,',
        48: 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.',
        49: 'Jeder soll mit Feuer gesalzen werden wie jedes Opfer mit Salz gesalzen wird.',
        50: 'Das Salz ist etwas Gutes. Doch wenn das Salz einmal schal geworden ist, womit wollt ihr es dann würzen? Habt Salz in euch und haltet Frieden mit einander!"',
    },
    10: {
        1: 'Er machte sich auf und zog in die Gegend von Judäa und über den Jordan. Und wieder sammelten sich bei ihm große Scharen, und wie gewöhnlich lehrte er sie wieder.',
        2: 'Da traten zu ihm Pharisäer, versuchten ihn und fragten, ob es dem Mann erlaubt sei, daß er sein Weib entlasse.',
        3: 'Er sprach zu ihnen: "Was hat euch Moses geboten?"',
        4: 'Sie sprachen: "Moses hat erlaubt, einen Scheidebrief zu schreiben und alsdann zu entlassen."',
        5: 'Doch Jesus sprach zu ihnen: "Nur eurer Herzenshärte wegen hat er dieses Gebot für euch geschrieben.',
        6: 'Doch im Anfang der Schöpfung schuf sie Gott als Mann und Weib.',
        7: 'So wird der Mann Vater und Mutter verlassen und sich seinem Weibe verbinden,',
        8: 'und diese zwei werden zu einem Fleische werden. So sind sie also nicht mehr zwei, vielmehr sind sie ein einziges Fleisch.',
        9: 'Was aber Gott vereinigt hat, das soll der Mensch nicht trennen."',
        10: 'Zu Hause fragten ihn dann seine Jünger noch einmal darüber.',
        11: 'Er sprach zu ihnen: "Wer sein Weib entläßt und eine andere heiratet, bricht ihr die Ehe;',
        12: 'und wenn sie ihren Mann entläßt und einen anderen heiratet, bricht sie die Ehe."',
        13: 'Man brachte zu ihm Kinder, damit er sie berühre. Allein die Jünger fuhren jene, die sie brachten, an.',
        14: 'Als Jesus dies bemerkte, ward er unwillig und sprach zu ihnen: "Laßt die Kinder zu mir kommen, wehrt es ihnen nicht; für solche ist das Reich Gottes!',
        15: 'Wahrlich, ich sage euch: Wer das Reich Gottes nicht aufnimmt wie ein Kind, kommt sicherlich nicht hinein."',
        16: 'Dann schloß er sie in seine Arme, legte ihnen seine Hände auf und gab ihnen den Segen.',
        17: 'Er machte sich wieder auf den Weg, da lief einer auf ihn zu, fiel vor ihm auf die Knie und fragte ihn: "Guter Meister, was muß ich tun, um das ewige Leben zu erwerben?"',
        18: 'Und Jesus sprach zu ihm: "Was nennst du mich \'gut\'? Niemand ist gut als Gott allein.',
        19: 'Du kennst die Gebote: \'Du sollst nicht töten!\' \'Du sollst nicht ehebrechen!\' \'Du sollst nicht stehlen!\' \'Du sollst kein falsches Zeugnis geben!\' \'Du sollst nicht betrügen!\' \'Du sollst Vater und Mutter ehren!\'"',
        20: 'Doch dieser sprach zu ihm: "All dies, Meister, habe ich von Jugend auf gehalten."',
        21: 'Und Jesus schaute ihn liebevoll an und sprach zu ihm: "Eines fehlt dir noch. Geh hin, verkaufe, was du hast, und schenke es den Armen; du wirst dann einen Schatz im Himmel haben. Dann komm und folge mir und trage dein Kreuz."',
        22: 'Bei diesen Worten ward er kleinmütig und ging betrübt von dannen, denn er besaß viele Güter.',
        23: 'Da schaute Jesus sich um und sprach zu seinen Jüngern: "Wie schwer geht es doch, daß die Reichen in das Reich Gottes gelangen!"',
        24: 'Die Jünger waren über seine Worte sehr betroffen. Doch Jesus sprach noch einmal zu ihnen: "Kinder! Wie schwer ist es doch für die, die auf ihr Geld vertrauen, in das Reich Gottes zu kommen!',
        25: 'Viel leichter geht ein Kamel durch ein Nadelöhr, als ein Reicher in das Reich Gottes."',
        26: 'Darauf erschraken sie noch mehr und sagten zueinander: "Wer kann da noch gerettet werden?"',
        27: 'Da sah sie Jesus an und sprach zu ihnen: "Bei den Menschen ist dies freilich unmöglich, doch nicht bei Gott; bei Gott ist alles möglich."',
        28: 'Da nahm Petrus das Wort und sprach: "Siehe, wir haben alles verlassen und sind dir nachgefolgt."',
        29: 'Und Jesus sprach: "Wahrlich, ich sage euch: Wer immer Haus, Brüder oder Schwestern, Mutter, Vater oder Kinder oder Äcker verläßt um meinetwillen und des Evangeliums wegen,',
        30: 'wird es hundertfach zurückerhalten: in dieser Welt an Häusern, an Brüdern, Schwestern, Müttern, Kindern und an Äckern, allerdings unter Verfolgung, und in der anderen Welt das ewige Leben.',
        31: 'Viele Erste werden Letzte und viele Letzte werden Erste sein."',
        32: 'Sie befanden sich auf dem Weg nach Jerusalem hinauf, und Jesus war ihnen stets weit voran, so daß sie sich entsetzten; sie folgten ihm, jedoch mit bangem Herzen. Er nahm die Zwölf wieder zu sich und begann mit ihnen über das zu sprechen, was ihm begegnen werde:',
        33: '"Seht, wir ziehen nach Jerusalem hinauf. Der Menschensohn wird den Oberpriestern und den Schriftgelehrten und Ältesten ausgeliefert werden, sie werden ihn zum Tod verdammen und ihn den Heiden übergeben.',
        34: 'Sie werden ihn verspotten und anspeien, geißeln und töten; doch nach drei Tagen wird er auferstehen."',
        35: 'Da traten Jakobus und Johannes, die Zebedäussöhne, zu ihm hin und sprachen: "Meister, wir möchten, daß du uns gewährst, um was wir dich bitten.',
        36: 'Er sprach zu ihnen: "Was soll ich euch tun?"',
        37: 'Sie antworteten ihm: "Verleihe uns, daß wir in deiner Herrlichkeit der eine dir zur Rechten, der andere dir zur Linken sitzen."',
        38: 'Doch Jesus sprach zu ihnen: "Ihr wißt nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken muß, die Taufe, die ich empfange, auch empfangen?"',
        39: 'Sie sagten ihm: "Wir können es." Doch Jesus sprach zu ihnen: "Den Kelch, den ich trinke, werdet ihr zwar trinken, und auch die Taufe empfangen, die ich empfange,',
        40: 'die Sitze zu meiner Rechten und zu meiner Linken aber, die kann ich nicht vergeben; denn sie gehören denen, für die sie schon bestimmt sind."',
        41: 'Als die anderen zehn das hörten, wurden sie unwillig über Jakobus und Johannes.',
        42: 'Doch Jesus rief sie zu sich her und sprach zu ihnen: "Ihr wißt: Die als Fürsten der Heidenvölker gelten, wollen über ihre Völker den Herrn spielen, und ihre Großen lassen sie ihre Macht fühlen.',
        43: 'Bei euch ist es aber nicht so; sondern wer unter euch ein Großer werden will, sei euer Diener,',
        44: 'und wer unter euch Erster sein will, sei der Knecht aller,',
        45: 'wie auch der Menschensohn nicht gekommen ist, bedient zu werden, vielmehr zu dienen, ja, sein Leben hinzuopfern als Lösegeld für viele."',
        46: 'So kamen sie nach Jericho. Als er mit seinen Jüngern und mit vielem Volke Jericho verließ, saß der Sohn des Timäus, der Bartimäus, ein blinder Bettler, am Wege.',
        47: 'Als er vernahm: Jesus von Nazareth ist es, begann er laut zu schreien und zu rufen: "Sohn Davids, Jesus, erbarme dich meiner!"',
        48: 'Da fuhren ihn viele an, er solle schweigen. Er aber rief nur um so lauter: "Sohn Davids, erbarme dich meiner!"',
        49: 'Darauf blieb Jesus stehen und sprach: "Ruft ihn her!" Da riefen sie den Blinden her und sagten ihm: "Sei guten Muts! Steh auf! Er ruft dich."',
        50: 'Da warf er seinen Mantel ab, sprang auf und kam zu Jesus.',
        51: 'Und Jesus sprach zu ihm: "Was soll ich dir tun?" Der Blinde sprach zu ihm: "Rabbuni, ich möchte wieder sehen können."',
        52: 'Und Jesus sprach zu ihm: "Geh hin, dein Glaube hat dir geholfen." Und sogleich konnte er sehen und folgte ihm auf dem Wege.',
    },
    11: {
        1: 'Sie kamen in die Nähe von Jerusalem, nach Bethphage und nach Bethanien am Ölberg. Er sandte zwei von seinen Jüngern',
        2: 'mit dem Auftrag fort: "Geht in das Dorf, das vor euch liegt. Gleich am Eingang findet ihr ein Füllen angebunden, auf dem noch niemals jemand saß. Löst es los und bringt es her!',
        3: 'Und sollte jemand zu euch sagen: \'Was macht ihr da?\' dann sagt: \'Der Herr braucht es. Er schickt es gleich wieder zurück."\'',
        4: 'Sie gingen weg und fanden am Hoftor ein Füllen angebunden, außen nach der Straße zu. Sie lösten es los.',
        5: 'Und einige von denen, die dort standen, fragten sie: "Was macht ihr da; ihr bindet ja das Füllen los?"',
        6: 'Doch sie erwiderten, wie Jesus ihnen aufgetragen hatte. Da ließ man sie gewähren.',
        7: 'Sie brachten das Füllen zu Jesus, legten ihre Kleider darauf, und er setzte sich darauf.',
        8: 'Und viele breiteten ihre Kleider auf den Weg, andere als Büschel das, was sie auf den Feldern abgeschnitten hatten.',
        9: 'Die vor und hinter ihm einhergingen, riefen: "Hosanna! Gepriesen sei, der im Namen des Herrn kommt!',
        10: 'Gepriesen sei das Reich unseres Vaters David, das jetzt erscheint. Hosanna in der Höhe!"',
        11: 'So zog er nach Jerusalem hinein in den Tempel. Er schaute alles ringsum an und ging nach Bethanien mit den Zwölfen, weil es schon spät war.',
        12: 'Als sie des anderen Tages wieder von Bethanien weggingen, empfand er Hunger.',
        13: 'Von weitem sah er einen Feigenbaum, voll mit Blättern, ging auf ihn zu, ob er nicht etwas an ihm fände. Doch wie er hinkam, fand er nichts als Blätter; es war nämlich noch nicht Feigenzeit.',
        14: 'Er aber sprach zu ihm: "Nie mehr, in Ewigkeit nicht, soll jemand von dir Frucht essen." Und seine Jünger hörten das.',
        15: 'Sie kamen nach Jerusalem. Da ging er in den Tempel und machte sich daran, die Käufer und Verkäufer aus dem Tempel auszutreiben. Die Tische der Wechsler und die Bänke der Taubenhändler stieß er um',
        16: 'und ließ es nicht geschehen, daß jemand ein Gefäß durch den Tempel trage.',
        17: 'Und er belehrte sie und sprach: "Steht denn nicht geschrieben: \'Mein Haus soll ein Bethaus heißen für alle Völker, doch ihr habt eine Räuberhöhle daraus gemacht."\'',
        18: 'Als dies die Oberpriester und die Schriftgelehrten hörten, suchten sie, wie sie ihn verderben könnten. Sie fürchteten ihn nämlich; es war ja alles Volk von seiner Lehre überwältigt.',
        19: 'Als es dann Abend wurde, entfernten sie sich aus der Stadt.',
        20: 'Als sie des anderen Morgens an dem Feigenbaum vorübergingen, da sahen sie, daß er von der Wurzel an ganz verdorrt war.',
        21: 'Da erinnerte sich Petrus und sprach zu ihm: "Rabbi, sieh, der Feigenbaum, den du verflucht hast, ist ganz verdorrt."',
        22: 'Und Jesus sprach zu ihnen: "Habt Glauben an Gott!',
        23: "Wahrlich, ich sage euch: Wenn einer zu dem Berg da spräche: 'Hebe dich hinweg und stürze dich ins Meer!' und er in seinem Innern nicht zweifelt, vielmehr glaubt, daß, was er sagt, geschehen wird, er wird es zustande bringen.",
        24: 'So sage ich euch denn: Um was ihr immer im Gebete bittet, glaubt nur, daß ihr es schon habt; dann wird es euch zuteil werden.',
        25: 'Und steht ihr zum Beten da, verzeiht, wenn ihr gegen jemand etwas habt, damit auch euer Vater in den Himmeln euch eure Sünden vergeben möge.',
        26: 'Wenn aber ihr nicht verzeiht, wird auch mein Vater, der in den Himmeln ist, euch eure Sünden nicht verzeihen."',
        27: 'Sie kamen wieder nach Jerusalem. Und während er im Tempel hin und her ging, näherten sich ihm die Oberpriester und die Schriftgelehrten sowie die Ältesten',
        28: 'und fragten ihn: "Mit welcher Vollmacht tust du das? Wer hat dir das Recht gegeben, dies zu tun?"',
        29: 'Doch Jesus sprach zu ihnen: "Auch ich will euch nach etwas fragen; gebt ihr mir Antwort, dann will auch ich euch sagen, mit welcher Vollmacht ich dies tue.',
        30: 'Kam die Johannestaufe vom Himmel oder von den Menschen? Gebt mir Antwort!"',
        31: 'Da überlegten sie miteinander und sprachen: "Sagen wir \'vom Himmel\', so wird er fragen: \'Warum habt ihr ihm dann nicht geglaubt?\'',
        32: 'Oder sollen wir sagen: \'Von Menschen?\'" Doch dazu fürchteten sie das Volk; denn alle hielten den Johannes für einen wirklichen Propheten.',
        33: 'Und so erwiderten sie Jesu: "Wir wissen es nicht." Darauf erwiderte ihnen Jesus: "Dann sage auch ich nicht, mit welcher Vollmacht ich dies tue."',
    },
    12: {
        1: 'Und dann begann er, in Gleichnissen zu ihnen zu reden. "Es pflanzte jemand einen Weinberg, umgab ihn mit einem Zaun, grub eine Kelter und baute einen Turm. Darauf verpachtete er ihn an Winzer und ging außer Landes.',
        2: 'Als nun die Zeit gekommen war, da schickte er einen Knecht zu den Winzern, um von den Winzern vom Ertrag des Weinbergs zu empfangen.',
        3: 'Doch diese packten ihn, schlugen ihn und schickten ihn mit leeren Händen heim.',
        4: 'Da schickte er ein zweitesmal einen anderen Knecht zu ihnen, doch sie mißhandelten auch diesen und beschimpften ihn.',
        5: 'Noch einen dritten schickte er; diesen brachten sie sogar ums Leben; und so noch viele andere, die sie teils mißhandelten, teils ermordeten.',
        6: "Nun hatte er noch einen, seinen vielgeliebten Sohn. Den schickte er zuletzt zu ihnen; er sagte sich: 'Vor meinem Sohne werden sie doch Achtung haben.'",
        7: "Doch jene Winzer sprachen zueinander: 'Das ist der Erbe; kommt, den töten wir; dann gehört sein Erbteil uns.'",
        8: 'Und sie ergriffen ihn und brachten ihn ums Leben und warfen ihn zum Weinberg hinaus.',
        9: 'Was wird wohl der Herr des Weinbergs tun? Er wird kommen und die Winzer töten und seinen Weinberg anderen anvertrauen.',
        10: "Habt ihr nie die Stelle in der Schrift gelesen: 'Der Stein, den die Bauleute verworfen haben, der ist zum Schlußstein geworden;",
        11: 'durch den Herrn ist dies geschehen, und es ist wunderbar in unseren Augen?\'"',
        12: 'Sie hätten sich seiner gern bemächtigt; allein sie fürchteten sich vor dem Volke. Sie hatten nämlich wohl erkannt, daß dieses Gleichnis ihnen gelte. So ließen sie ihn stehen und gingen weg.',
        13: 'Sie schickten alsdann einige von den Pharisäern und den Herodianern zu ihm, damit sie ihn mit einer Rede fangen sollten.',
        14: 'Sie kamen und sagten zu ihm: "Meister, wir wissen, daß du wahrhaftig bist; du fragst nach niemand; du siehst nicht auf die Stellung der Menschen, sondern lehrst den Weg Gottes in Wahrheit: Darf man dem Kaiser Steuer zahlen oder nicht? Sollen wir bezahlen oder nicht?"',
        15: 'Doch er erkannte ihre Heuchelei und sprach zu ihnen: "Warum versucht ihr mich? Zeigt mir einen Denar, damit ich sehe."',
        16: 'Sie reichten einen hin. Er fragte sie: "Wessen Bild und Aufschrift ist das?" "Des Kaisers", gaben sie ihm zur Antwort.',
        17: 'Darauf entgegnete ihnen Jesus: "So gebt dem Kaiser, was des Kaisers, und Gott, was Gottes ist." Und sie staunten über ihn.',
        18: 'Jetzt kamen die Sadduzäer zu ihm; - diese leugnen, daß es eine Auferstehung gebe - sie fragten ihn:',
        19: '"Meister, bei Moses steht geschrieben: \'Wenn irgend jemands Bruder stirbt und er ein Weib, doch kein Kind hinterläßt, dann soll der Bruder dessen Weib heiraten und seinem Bruder Nachkommen erwecken.\'',
        20: 'Da waren sieben Brüder. Der erste nahm ein Weib; doch er starb kinderlos.',
        21: 'Darauf nahm sie der zweite; allein auch er starb kinderlos und ebenso der dritte;',
        22: 'alle sieben blieben kinderlos. Zuletzt von allen starb dann auch das Weib.',
        23: 'Wessen Weib wird sie nun bei der Auferstehung sein; - gesetzt den Fall, daß sie wirklich auferstehen - denn alle sieben haben sie zum Weibe gehabt?"',
        24: 'Und Jesus sprach zu ihnen: "Liegt nicht schon darin euer Irrtum, daß ihr weder die Schriften noch die Allmacht Gottes kennt?',
        25: 'Denn wenn man von den Toten aufersteht, dann heiratet man nicht mehr und wird auch nicht verheiratet; man ist vielmehr so wie die Engel in den Himmeln.',
        26: "Was aber die Auferstehung der Toten betrifft, habt ihr nicht im Buche Mosis gelesen, wie bei der Stelle von dem Dornbusch Gott zu ihm sprach: 'Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs'?",
        27: 'Gott ist doch nicht ein Gott der Toten, sondern der Lebendigen. Ihr irrt euch also gewaltig."',
        28: 'Ein Schriftgelehrter, der ihrem Wortstreit zugehört hatte und einsah, daß er ihnen gut erwidert hatte, trat herzu und fragte ihn: "Was ist das erste unter allen Geboten?"',
        29: 'Und Jesus sprach: "Das erste ist: \'Höre, Israel, der Herr unser Gott ist allein der Herr.',
        30: "Du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen, aus deiner ganzen Seele, aus deinem ganzen Gemüte und deiner ganzen Kraft.' Dies ist das erste Gebot.",
        31: 'Das zweite lautet: \'Du sollst deinen Nächsten lieben wie dich selbst.\' Ein größeres Gebot als diese gibt es nicht."',
        32: 'Da sprach zu ihm der Schriftgelehrte: "Vortrefflich, Meister! Ganz richtig hast du ausgeführt, daß er nur einer ist und daß kein anderer ist außer ihm.',
        33: 'Auch das \'Ihn lieben aus ganzem Herzen und aus ganzem Gemüte und aus aller Kraft\', und das \'Du sollst den Nächsten lieben wie dich selbst\', ist wertvoller als alle Brand- und anderen Opfer."',
        34: 'Als Jesus vernahm, wie er so verständig Antwort gab, sprach er zu ihm: "Du bist nicht mehr weit vom Reiche Gottes entfernt." Und keiner wagte mehr, ihn etwas zu fragen.',
        35: 'Als Jesus dann im Tempel lehrte, fragte er: "Wie können die Schriftgelehrten sagen, der Christus sei der Sohn Davids?',
        36: "Sagt doch David selbst im Heiligen Geist: 'Es sprach der Herr zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde dir als Schemel zu Füßen lege.'",
        37: 'So nennt ihn David also selber \'Herr\': Wie kann er dann sein Sohn sein?" Die große Menge hörte ihm gerne zu.',
        38: 'Und weiter sagte er in seiner Lehre: "Hütet euch vor den Schriftgelehrten! Sie lieben es, in langen Kleidern einherzugehen, auf den öffentlichen Plätzen gegrüßt zu werden,',
        39: 'in der Synagoge die Ehrensitze einzunehmen und bei den Gastmählern die Ehrenplätze.',
        40: 'Sie verprassen die Häuser der Witwen und sagen nur zum Schein lange Gebete dafür her. Eine härtere Strafe erwartet diese."',
        41: 'Er saß dem Opferkasten gegenüber und schaute zu, wie das Volk in den Opferkasten sein Geld einwarf, und viele Reiche warfen viel hinein.',
        42: 'Auch eine bettelarme Witwe kam herbei und warf zwei Heller ein, das heißt soviel wie einen Pfennig.',
        43: 'Da rief er seine Jünger zu sich her und sprach zu ihnen: "Wahrlich, ich sage euch: Diese arme Witwe gab mehr in den Opferkasten als alle anderen, die etwas hineingeworfen haben.',
        44: 'Denn alle warfen von ihrem Überfluß hinein; sie aber gab in ihrer Armut alles, was sie hatte, ihren ganzen Lebensunterhalt."',
    },
    13: {
        1: 'Als er den Tempel verließ, da redete ihn einer seiner Jünger an: "Schau, Meister, was für Steine, was für Bauten!"',
        2: 'Doch Jesus sprach zu ihm: "Siehst du die so gewaltigen Bauten? Hier wird kein Stein auf dem anderen bleiben, der nicht niedergerissen werden wird."',
        3: 'Dann ließ er sich dem Tempel gegenüber auf dem Ölberg nieder; da fragten ihn Petrus, Jakobus, Johannes und Andreas im geheimen:',
        4: '"Sag uns: Wann wird das geschehen, und welches wird das Zeichen sein, wann all das sich zu vollenden beginnt?"',
        5: 'Da fing Jesus an, ihnen zu erklären: "Seht zu, daß euch niemand irreführe.',
        6: "Viele werden unter meinem Namen kommen und behaupten: 'Ich bin es.' Und sie werden viele irreführen.",
        7: 'Wenn ihr von Kriegen und von Kriegsgerüchten hört, so laßt euch nicht erschrecken. Denn das muß geschehen, doch es ist noch nicht das Ende.',
        8: 'Denn Volk wird sich gegen Volk erheben und Reich gegen Reich; an vielen Orten wird es Erdbeben geben, und Hungersnöte werden sein; doch dies ist erst der Anfang der Wehen.',
        9: 'Doch. seht euch für euch selber vor. Man wird euch den Gerichten übergeben und euch in Synagogen geißeln; vor Statthalter und Könige wird man euch um meinetwillen stellen, ihnen zum Zeugnis.',
        10: 'Doch zuvor muß bei allen Völkern das Evangelium verkündet werden.',
        11: 'Wenn ihr dann den Gerichten ausgeliefert werdet, so macht euch vorher keine Sorge, was ihr reden sollt, vielmehr was euch in jener Stunde eingegeben wird, das saget. Denn alsdann seid nicht ihr es, die da reden; es ist vielmehr der Heilige Geist.',
        12: 'Der Bruder wird den eigenen Bruder zum Tode überliefern, der Vater das eigene Kind; Kinder werden gegen ihre Eltern auftreten und sie in den Tod bringen.',
        13: 'Von allen werdet ihr um meines Namens willen gehaßt werden, doch wer ausharrt bis ans Ende, wird gerettet werden.',
        14: 'Wenn ihr jedoch den Greuel der Verwüstung dort herrschen seht, wo es nicht sein soll - der Leser möge dies wohl beachten -, dann fliehe ins Gebirge, wer in Judäa ist.',
        15: 'Wer auf dem Dache ist, der steige nicht in sein Haus hinab; auch gehe er nicht hinein, um irgend etwas aus seinem Hause zu holen.',
        16: 'Wer auf dem Felde ist, der wende sich nicht um, sein Oberkleid zu holen.',
        17: 'Doch wehe den Frauen, die in jenen Tagen ein Kindlein unterm Herzen oder an der Brust tragen.',
        18: 'Betet, daß dies nicht zur Winterszeit geschehe.',
        19: 'Jene Tage werden nämlich eine Trübsal bedeuten, wie sie noch nie gewesen, seitdem Gott im Anfang die Schöpfung schuf bis jetzt, noch auch jemals sein wird.',
        20: 'Und hätte der Herr die Tage nicht abgekürzt, so würde niemand gerettet werden. Doch um der Auserwählten willen, die er sich auserwählte, hat er die Tage abgekürzt.',
        21: "Wenn dann jemand zu euch sagt: 'Siehe, hier ist Christus.' 'Siehe, dort.' Glaubt es nicht!",
        22: 'Denn falsche Christusse und falsche Propheten werden sich erheben: Sie werden Zeichen und Wunder tun, so daß, wenn es möglich wäre, sogar die Auserwählten verführt würden.',
        23: 'So seht euch vor! Seht, ich sage euch alles vorher.',
        24: 'Sogleich nach der Trübsal jener Tage wird sich die Sonne verfinstern; der Mond wird seinen Schein nicht geben;',
        25: 'die Sterne werden vom Himmel fallen, die Kräfte des Himmels erschüttert werden.',
        26: 'Dann wird man den Menschensohn auf Wolken kommen sehen mit großer Macht und Herrlichkeit.',
        27: 'Dann wird er seine Engel aussenden und seine Auserwählten sammeln von den vier Richtungen des Windes, von der Erde tiefstem Ende bis zum höchsten Himmel.',
        28: 'Vom Feigenbaum aber lernt es im Gleichnis: Wenn seine Zweige einmal saftig werden und er schon Blätter treibt, dann wisset ihr: Der Sommer ist nahe.',
        29: 'So sollt auch ihr, wenn ihr dies geschehen seht, erkennen, daß es schon vor der Türe steht.',
        30: 'Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis all dies geschehen wird.',
        31: 'Himmel und Erde werden vergehen, doch meine Worte werden nicht vergehen.',
        32: 'Von jenem Tag aber und der Stunde weiß niemand etwas, nicht die Engel des Himmels, auch nicht der Sohn, sondern nur der Vater.',
        33: 'So seid denn auf der Hut; seid wachsam betet! Ihr wißt ja nicht, wann der Zeitpunkt da ist.',
        34: 'Es wird euch ergehen wie einem Manne, der in die Fremde ziehen wollte: Er verließ sein Haus, gab seinen Knechten alle Vollmacht, wies einem jeden seine Arbeit zu; dem Torhüter trug er auf, wachsam zu sein.',
        35: 'So seid denn wachsam; ihr wißt nicht, wann der Herr des Hauses kommt, ob spät am Abend oder erst um Mitternacht, ob beim Hahnenschrei oder am frühen Morgen.',
        36: 'Er könnte unerwartet kommen und euch schlafend finden.',
        37: 'Was ich euch sage, gilt allen: Wachet!"',
    },
    14: {
        1: 'Ostern, das Fest der ungesäuerten Brote, war in zwei Tagen. Die Oberpriester und die Schriftgelehrten suchten nach einer passenden Gelegenheit, wie sie ihn mit List ergreifen und dann töten könnten.',
        2: 'Doch sagten sie: "Nur nicht am Fest, es könnte sonst das Volk in Aufruhr kommen."',
        3: 'Als Jesus in Bethanien weilte, im Hause Simons des Aussätzigen, da trat, solange er zu Tische lag, ein Weib herein; sie trug ein Gefäß aus Alabaster voll echten, feinsten Nardenöls. Sie zerbrach das Alabastergefäß und goß das Öl über seinem Haupte aus.',
        4: 'Darüber waren einige untereinander sehr erbost: "Wozu die Verschwendung mit dem Salböl?',
        5: 'Man hätte die Salbe um mehr als dreihundert Denare verkaufen und den Erlös den Armen geben können." So ließen sie das Weib hart an.',
        6: 'Doch Jesus sprach: "Laßt sie! Was kränkt ihr sie? Sie hat ein gutes Werk an mir getan.',
        7: 'Die Armen habt ihr allzeit bei euch und könnt ihnen Gutes tun, wann ihr wollt, mich aber habt ihr nicht allzeit.',
        8: 'Sie hat getan, was sie konnte; sie salbte meinen Leib zum voraus für das Begräbnis.',
        9: 'Wahrlich, ich sage euch: Wo immer in der ganzen Welt dieses Evangelium verkündet wird, da wird man auch erzählen, was sie getan hat, ihr zum Gedächtnis."',
        10: 'Alsdann ging einer von den Zwölfen, Judas Iskariot, zu den Oberpriestern, um ihn diesen zu verraten.',
        11: 'Wie sie dies hörten, freuten sie sich sehr, und sie versprachen, ihm Geld zu geben. Er ging nun darauf aus, ihn zu gelegener Zeit auszuliefern.',
        12: 'Am ersten Tag der Ungesäuerten Brote, an dem man das Osterlamm zu schlachten pflegte, fragten ihn seine Jünger: "Wo willst du, daß wir dir das Ostermahl bereiten?"',
        13: 'Da sandte er zwei aus seinen Jüngern ab und sprach zu ihnen: "Geht in die Stadt! Dort wird euch ein Mann mit einem Wasserkrug begegnen; dem folgt.',
        14: "Wo der hingeht, da sagt zu dem Herrn des Hauses: 'Der Meister spricht: Wo ist mein Gemach, in dem ich mit meinen Jüngern das Ostermahl halten kann?'",
        15: 'Er wird euch ein oberes Gemach anweisen, geräumig, mit Teppichen belegt und hergerichtet; dort bereitet es für uns!"',
        16: 'Die Jünger gingen weg und kamen in die Stadt; sie fanden es so, wie er es ihnen gesagt hatte, und sie bereiteten das Ostermahl.',
        17: 'So ward es Abend. Da kam er mit den Zwölfen.',
        18: 'Während sie bei Tische waren und aßen, sprach Jesus: "Wahrlich, ich sage euch: Einer aus euch wird mich verraten, einer, der mit mir ißt."',
        19: 'Da fragte ihn einer nach dem anderen tief betrübt: "Doch nicht ich?"',
        20: 'Er sprach zu ihnen: "Einer aus den Zwölfen, der mit mir aus einer Schüssel ißt.',
        21: 'Zwar geht der Menschensohn dahin, wie es von ihm geschrieben steht; doch wehe jenem Menschen, durch den der Menschensohn verraten wird. Besser wäre es für ihn, wenn dieser Mensch nicht geboren wäre."',
        22: 'Während sie beim Mahle waren, nahm Jesus Brot, segnete, brach es und gab es ihnen mit den Worten: "Nehmt hin, das ist mein Leib."',
        23: 'Darauf nahm er den Kelch, dankte und gab ihnen diesen, und sie tranken daraus alle.',
        24: 'Er sprach zu ihnen: "Das ist mein Bundesblut, das für viele vergossen wird.',
        25: 'Wahrlich, ich sage euch: Ich werde nicht mehr vom Gewächs des Weinstocks trinken bis zu jenem Tage, da ich es im Gottesreiche erneuert trinken werde."',
        26: 'Sie beteten den Lobgesang und gingen hierauf zum Ölberg hinaus.',
        27: 'Und Jesus sprach zu ihnen: "Ihr alle werdet heute nacht an mir irre werden; denn also steht geschrieben: \'Ich will den Hirten schlagen; dann werden die Schafe zerstreut werden.\'',
        28: 'Nach meiner Auferstehung aber will ich euch nach Galiläa vorausgehen."',
        29: 'Darauf gab ihm Petrus zur Antwort: "Und mögen alle an dir irre werden, ich nicht."',
        30: 'Doch Jesus sprach zu ihm: "Wahrlich, ich sage dir: Heute noch, in dieser Nacht, noch vor dem zweiten Hahnenschrei, wirst du mich dreimal verleugnet haben."',
        31: 'Allein nur um so eifriger sprach er: "Und wenn ich mit dir sterben müßte, ich werde dich nicht verleugnen." In gleicher Weise sprachen alle.',
        32: 'Sie kamen zu einem Landgut, Gethsemani geheißen. Er sprach zu seinen Jüngern: "Wartet hier, indes ich bete."',
        33: 'Nur Petrus, Jakobus und Johannes nahm er mit sich. Da fing er an, zu zittern und zu zagen.',
        34: 'Er sprach zu ihnen: "Meine Seele ist bis zum Tod betrübt; bleibet hier und wachet!"',
        35: 'Er ging ein wenig vorwärts, fiel auf die Erde nieder und betete, daß, wenn es möglich sei, die Stunde an ihm vorübergehe.',
        36: 'Er sprach: "Abba, Vater, dir ist alles möglich; laß diesen Kelch an mir vorübergehen. Doch nicht, wie ich will, sondern wie du willst."',
        37: 'Dann ging er wieder hin und fand sie schlafend. Er sprach zu Petrus: "Simon, du schläfst? Nicht eine einzige Stunde hast du wachen können?',
        38: 'Wachet und betet, damit ihr nicht in Versuchung fallet. Der Geist ist willig; doch das Fleisch ist schwach."',
        39: 'Dann ging er wieder hin und betete mit denselben Worten.',
        40: 'Er kam zurück und fand sie wieder schlafend; denn ihre Augen waren schwer geworden; sie wußten nicht, was sie zu ihm sagen sollten.',
        41: 'Als er zum drittenmal kam, sprach er zu ihnen: "Noch schlafet ihr und ruhet. Nun ist es soweit. Die Stunde ist gekommen, da der Menschensohn in die Hände der Sünder überliefert wird.',
        42: 'Steht auf und laßt uns gehen. Seht, mein Verräter naht."',
        43: 'Noch sprach er so, da kam schon Judas, einer aus den Zwölfen, mit ihm ein Haufen mit Schwertern und mit Prügeln im Auftrag der Oberpriester, der Schriftgelehrten und der Ältesten.',
        44: 'Sein Verräter hatte mit ihnen ein Zeichen verabredet: "Der, den ich küssen werde, ist es. Den packt und führt ihn vorsichtig weg."',
        45: 'Er ging sofort auf Jesus zu und sagte zu ihm: "Sei gegrüßt, Rabbi!" und küßte ihn gar innig.',
        46: 'Sie aber legten Hand an Jesus und ergriffen ihn.',
        47: 'Doch einer von denen, die in der Nähe standen, zog sein Schwert und schlug den Knecht des Hohenpriesters und hieb ihm ein Ohr ab.',
        48: 'Und Jesus sprach zu ihnen: "Wie gegen einen Räuber seid ihr ausgezogen, mit Schwertern und Prügeln, um mich zu ergreifen.',
        49: 'Tag für Tag war ich bei euch im Tempel, wo ich lehrte, und ihr habt mich nicht ergriffen. Jedoch es sollen sich die Schriften erfüllen."',
        50: 'Jetzt ließen ihn alle seine Jünger im Stich und flohen.',
        51: 'Ein Jüngling, der ein Linnentuch auf bloßem Leibe trug, folgte ihm. Da packte man ihn.',
        52: 'Er aber ließ das Linnentuch fahren und floh vor ihnen nackt.',
        53: 'Sie führten Jesus zum Hohenpriester, bei dem sich alle versammelten, die Oberpriester und die Ältesten und Schriftgelehrten.',
        54: 'Petrus folgte ihm von ferne bis in den Hof des Hohenpriesters hinein. Dort setzte er sich bei den Dienern nieder und wärmte sich am Feuer.',
        55: 'Die Oberpriester, das heißt der ganze Hohe Rat, suchten nach einem Zeugnis gegen Jesus, um ihn in den Tod zu bringen. Sie fanden aber keines,',
        56: 'obwohl gar viele falsches Zeugnis über ihn abgaben; ihr Zeugnis stimmte nicht zusammen.',
        57: 'Dann traten einige noch auf und sagten als falsche Zeugen gegen ihn:',
        58: '"Wir haben diesen sagen hören: \'Ich reiße diesen Tempel hier, der mit Händen erbaut wurde, nieder und baue innerhalb drei Tagen einen anderen auf, der nicht mit Händen erbaut wird.\'"',
        59: 'Doch auch so stimmte, was sie sagten, nicht zusammen.',
        60: 'Da trat der Hohepriester mitten hin und fragte Jesus: "Weißt du denn gar nichts zu erwidern? Was bezeugen doch diese gegen dich?"',
        61: 'Er aber schwieg und gab ihm keine Antwort. Und wieder fragte ihn der Hohepriester: "Bist du der Christus, der Sohn Gottes des Hochgelobten?"',
        62: 'Und da sprach Jesus: "Ich bin es. Ihr werdet den Menschensohn zur Rechten des Allmächtigen Gottes sitzen und auf den Wolken des Himmels kommen sehen."',
        63: 'Da zerriß der Hohepriester seine Kleider und rief: "Was brauchen wir noch Zeugen?',
        64: 'Ihr habt die Lästerung gehört. Was dünkt euch?" Und alle sprachen ihn des Todes schuldig.',
        65: 'Alsdann begannen einige, ihn anzuspeien, sein Antlitz zu verhüllen, ihm Stockschläge zu geben und ihm zuzurufen: "Weissage!" Und auch die Diener fielen über ihn her.',
        66: 'Indes befand sich Petrus im Hofe draußen. Da kam eine von den Mägden des Hohenpriesters;',
        67: 'sie sah den Petrus, der sich wärmte, schaute ihm ins Gesicht und sprach: "Auch du warst bei Jesus, dem Nazarener."',
        68: 'Er aber leugnete und sagte: "Ich weiß nicht und verstehe nicht, was du redest." Er ging alsdann zur Vorhalle hinaus, und schon krähte der Hahn.',
        69: 'Wie ihn die Magd da sah, fing sie noch einmal an und sprach zu denen, die dort standen. "Auch der gehört zu ihnen."',
        70: 'Er leugnete es abermals. Nach einer kleinen Weile sagten die Umstehenden nochmals zu Petrus: "Sicherlich gehörst du auch zu ihnen; du bist ja auch ein Galiläer."',
        71: 'Da fing er an zu fluchen und zu schwören: "Ich kenne diesen Menschen nicht, von dem ihr redet."',
        72: 'Da krähte gleich darauf der Hahn ein zweitesmal. Und nun erinnerte sich Petrus des Wortes Jesu, als er zu ihm sprach: "Noch vor dem zweiten Hahnenschrei wirst du mich dreimal verleugnet haben." Und er brach in Tränen aus.',
    },
    15: {
        1: 'Die Hohenpriester, Ältesten und Schriftgelehrten, das heißt der ganze Hohe Rat, hielten sofort am Morgen eine Sitzung. Sie führten Jesus gefesselt ab und übergaben ihn dem Pilatus.',
        2: 'Pilatus fragte ihn: "Bist du der Judenkönig?" Und Jesus sprach zu ihm: "Das sagst nur du!"',
        3: 'Die Oberpriester wußten ihn in vielem anzuklagen.',
        4: 'Da fragte ihn Pilatus abermals: "Weißt du denn gar nichts zu erwidern? Sieh, was diese alles gegen dich vorbringen."',
        5: 'Doch Jesus gab überhaupt keine Antwort mehr, so daß Pilatus sich verwunderte.',
        6: 'Nun pflegte er ihnen auf den Festtag einen Gefangenen loszugeben, den sie sich selbst ausbitten durften.',
        7: 'Da lag nun einer im Gefängnis, er hieß Barabbas, und mit ihm andere Aufrührer, die beim Aufruhr einen Mord begangen hatten.',
        8: 'Das Volk zog hinauf und fing an unter lautem Schreien zu fordern, das ihnen zu gewähren, was er immer noch getan.',
        9: 'Pilatus fragte sie: "Wollt ihr, daß ich euch den Judenkönig freilasse?"',
        10: 'Er wußte nämlich wohl, daß ihn die Oberpriester aus Neid überliefert hatten.',
        11: 'Die Oberpriester hetzten die Menge auf, er möge ihnen eher den Barabbas freilassen.',
        12: 'Da fragte sie Pilatus noch einmal: "Was soll ich aber dann mit diesem anfangen, den ihr den Judenkönig heißt?"',
        13: 'Sie schrien wiederum: "Ans Kreuz mit ihm."',
        14: 'Jedoch Pilatus sprach zu ihnen: "Was hat er denn Böses getan?" Da schrien sie noch lauter: "Ans Kreuz mit ihm!"',
        15: 'Pilatus aber wollte sich dem Volk gefällig zeigen, so gab er ihnen den Barabbas frei, Jesus aber überließ er ihnen, daß er gegeißelt und gekreuzigt würde.',
        16: 'Die Soldaten führten ihn in den Hof hinein, das heißt in das Gerichtsgebäude, und versammelten um ihn die ganze Abteilung.',
        17: 'Sie behängten ihn mit einem scharlachroten Mantel, flochten eine Dornenkrone und setzten sie ihm auf.',
        18: 'Alsdann begannen sie, ihn zu begrüßen: "Heil dir, du Judenkönig!"',
        19: 'Sie schlugen ihn mit dem Rohr auf das Haupt, spieen ihn an und beugten huldigend vor ihm die Knie.',
        20: 'Nachdem sie ihren Spott mit ihm getrieben hatten, nahmen sie ihm den Mantel ab und zogen ihm die eigenen Kleider wieder an. Dann führten sie ihn ab zur Kreuzigung.',
        21: 'Sie zwangen einen, der vorüberging, den Simon von Cyrene, der von seinem Landgut kam, den Vater des Alexander und Rufus, ihm das Kreuz nachzutragen.',
        22: 'Sie führten ihn nach dem Orte Golgotha, das heißt Schädelstätte,',
        23: 'und gaben ihm Wein, vermischt mit Myrrhe. Er nahm ihn aber nicht.',
        24: 'Dann kreuzigten sie ihn und verteilten seine Kleider unter sich, indem sie das Los darüber warfen, was ein jeder haben sollte.',
        25: 'Es war die dritte Stunde, als sie ihn kreuzigten.',
        26: 'Auch eine Inschrift, die seine Schuld angab, war angeschrieben: "Der Judenkönig."',
        27: 'Zugleich mit ihm kreuzigte man auch zwei Räuber, den einen zu seiner Rechten, den anderen zur Linken.',
        28: 'So ward die Schrift erfüllt: "Er wird den Missetätern beigezählt."',
        29: 'Die Vorübergehenden überhäuften ihn mit Lästerworten; sie schüttelten den Kopf und sprachen: "He du, der du den Tempel hast zerstören und ihn in drei Tagen wieder aufbauen wollen,',
        30: 'rette dich selbst und steige herab vom Kreuz."',
        31: 'Ähnlich höhnten auch die Oberpriester; sie und die Schriftgelehrten sagten zueinander: "Andere hat er gerettet; sich selbst kann er nicht retten.',
        32: 'Christus, der König Israels, steige jetzt herab vom Kreuz, auf daß wir es sehen und glauben." Selbst die mit ihm gekreuzigt waren, schmähten ihn.',
        33: 'Von der sechsten Stunde an lag auf dem ganzen Land eine Finsternis und dauerte bis zur neunten Stunde.',
        34: 'Und um die neunte Stunde rief Jesus mit lauter Stimme aus: "Eloi, eloi, lama sabachthani!", das heißt: "Mein Gott, mein Gott, warum hast du mich verlassen?"',
        35: 'Und einige von denen, die dort standen, vernahmen dies und sagten: "Seht, er ruft Elias."',
        36: 'Da lief sogleich einer aus ihnen hin und füllte einen Schwamm mit Essig, steckte ihn auf ein Rohr und gab ihm zu trinken mit den Worten: "Laßt mich, wir wollen sehen, ob Elias wirklich kommt und ihn herabnimmt."',
        37: 'Doch Jesus stieß noch einen lauten Schrei aus und verschied.',
        38: 'Und der Vorhang im Tempel riß entzwei, von oben bis unten.',
        39: 'Als der Hauptmann, der ihm gegenüberstand, gewahrte, daß er so verschieden sei, rief er aus: "Wahrlich, dieser Mensch war Gottes Sohn."',
        40: 'Auch Frauen waren dort; die schauten aus der Ferne zu. Unter ihnen waren Maria Magdalena, Maria, die Mutter des jüngeren Jakobus und des Joses, und Salome.',
        41: 'Sie waren ihm schon in Galiläa gefolgt und hatten ihm gedient. Noch viele andere waren da, die mit ihm nach Jerusalem hinaufgegangen waren.',
        42: 'Als es Abend war - es war ja Rüsttag, das ist der Tag vor dem Sabbat-,',
        43: 'kam Joseph von Arimathäa, ein angesehener Ratsherr, der selber auch das Reich Gottes erwartete. Mutig ging er zu Pilatus und bat ihn um den Leichnam Jesu.',
        44: 'Pilatus war erstaunt, daß er schon tot sein sollte, er ließ den Hauptmann kommen und fragte ihn, ob er schon tot sei.',
        45: 'Als er es vom Hauptmann erfahren hatte, schenkte er den Leichnam dem Joseph.',
        46: 'Und dieser kaufte Leinwand, nahm ihn ab und wickelte ihn in die Leinwand. Darauf legte er ihn in ein Grab, das aus einem Felsen ausgehauen war, und wälzte vor den Eingang des Grabes einen Stein.',
        47: 'Maria Magdalena und Maria, die Mutter des Joses, sahen zu, wohin er gelegt wurde.',
    },
    16: {
        1: 'Als der Sabbat vorüber war, kauften Maria Magdalena, Maria, die Mutter des Jakobus, und Salome Spezereien, um hinauszugehen und ihn zu salben.',
        2: 'Ganz früh am Morgen des ersten Wochentages, wie die Sonne eben aufgegangen war, kamen sie zum Grabe.',
        3: 'Sie sagten zueinander: "Wer mag uns wohl den Stein vom Eingange des Grabes wegwälzen?"',
        4: 'Als sie hinblickten, sahen sie, daß der Stein weggewälzt war; er war wirklich sehr groß.',
        5: 'Sie gingen in das Grab hinein und sahen zur Rechten einen Jüngling sitzen, angetan mit einem weißen Gewande. Und sie entsetzten sich.',
        6: 'Er aber sprach zu ihnen: "Entsetzt euch nicht! Ihr sucht Jesus von Nazareth, den Gekreuzigten, er ist auferstanden, er ist nicht mehr hier. Seht den Platz, wohin man ihn gelegt hatte.',
        7: 'Doch geht schnell hinweg und sagt seinen Jüngern und dem Petrus, daß er euch nach Galiläa vorangeht. Dort werdet ihr ihn sehen, so wie er es euch gesagt hat."',
        8: 'Sie gingen rasch hinaus und eilten schnell vom Grab hinweg; denn Zittern und Entsetzen hatte sie erfaßt. Sie sagten niemand etwas; denn sie hatten Angst.',
        9: 'So war er in der Frühe des ersten Wochentages auferstanden und erschien zuerst der Maria Magdalena, aus der er sieben Dämonen ausgetrieben hatte.',
        10: 'Und diese ging hin und verkündete es denen, die bei ihm gewesen waren und jetzt trauerten und weinten.',
        11: 'Als sie hörten, daß er lebe und ihr erschienen sei, da wollten sie es nicht glauben.',
        12: 'Später erschien er noch zwei anderen aus ihnen unterwegs in einer andersartigen Gestalt, als sie über Land gingen.',
        13: 'Auch jene gingen hin und erzählten es den übrigen; jedoch auch ihnen wollten sie nicht glauben.',
        14: 'Zuletzt erschien er den Elfen selbst, als sie zu Tische saßen. Er rügte ihren Unglauben und ihre Herzenshärte, weil sie denen nicht geglaubt hatten, die ihn als einen von den Toten Auferstandenen gesehen hatten.',
        15: 'Hierauf sprach er zu ihnen: "Gehet hin in alle Welt und verkündet die frohe Botschaft der ganzen Schöpfung!',
        16: 'Wer glaubt und sich taufen läßt, wird gerettet werden, wer aber nicht glaubt, wird verdammt werden.',
        17: 'Und diese Zeichen werden die Glaubenden begleiten: In meinem Namen werden sie Dämonen austreiben; sie werden in neuen Sprachen reden;',
        18: 'sie werden Schlangen aufheben, und sollten sie Tödliches trinken, werden sie nicht Schaden leiden; Kranken werden sie die Hände auflegen, und sie werden gesund werden."',
        19: 'So sprach der Herr Jesus zu ihnen. Darauf ward er in den Himmel aufgenommen und setzte sich zur Rechten Gottes.',
        20: 'Sie aber zogen aus und predigten überall. Der Herr wirkte mit ihnen, und er gab ihrer Rede Kraft durch die nachfolgenden Wunderzeichen.',
    },
}
